function formatEventTime(value){ return new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(new Date(value)).replace(',', ' ·'); }
function followUpLabel(value){ const date=new Date(value); const now=new Date(); const dayStart=new Date(now.getFullYear(),now.getMonth(),now.getDate()); const dueStart=new Date(date.getFullYear(),date.getMonth(),date.getDate()); const diff=Math.round((dueStart-dayStart)/86400000); if(diff<=0)return 'Today'; if(diff===1)return 'Tomorrow'; if(diff===2)return 'In 2 days'; if(diff===3)return 'In 3 days'; return 'Next week'; }
function normalizeData(data){
  const followUpById=new Map(data.followUps.map(f=>[f.id,f]));
  const students=data.students.map(s=>{const guardian=s.guardians?.[0];return {...s,parent:guardian?.name??'Parent',relation:guardian?.relation??'Guardian',phone:guardian?.phone??'',guardianId:guardian?.id??null,guardians:(s.guardians||[]).map(g=>({id:g.id,name:g.name??'',relation:g.relation??'',phone:g.phone??''}))};});
  const rawEvents=data.events.map(e=>{const followUp=followUpById.get(e.follow_up_id);const plannedTopic=e.planned_topic||null;const discussedTopics=e.discussed_topics||((e.result==='Connected'&&e.topic)?[e.topic]:[]);return {id:e.id,studentId:e.student_id,guardianId:e.guardian_id,result:e.result,duration:formatCallDuration(e.duration_seconds),durationSeconds:e.duration_seconds,attemptNumber:e.attempt_number,topic:e.topic,plannedTopic,discussedTopics,note:e.teacher_note,callTime:e.call_time,time:formatEventTime(e.call_time),dateKey:new Date(e.call_time).toDateString()===new Date().toDateString()?'today':'older',followUp:followUp?followUpLabel(followUp.due_at):null,provider:e.provider,providerCallId:e.provider_call_id,providerStatus:e.provider_status,endedAt:e.ended_at};});
  const events=rawEvents.map(event=>({...event,attemptNumber:cycleAttemptNumber(rawEvents,event)}));
  const aiBriefs={};
  for(const brief of data.aiBriefs||[]){
    if(!aiBriefs[brief.student_id] || brief.version>aiBriefs[brief.student_id].version) aiBriefs[brief.student_id]={id:brief.id,version:brief.version,status:brief.status,brief:{key_topics:brief.key_topics||[],parent_concerns:brief.parent_concerns||[],recorded_resolutions:brief.recorded_resolutions||[],open_items:brief.open_items||[],suggested_next_step:brief.suggested_next_step||''},generatedAt:brief.generated_at};
  }
  return { students, events, followUps:data.followUps.map(f=>({...f,studentId:f.student_id,guardianId:f.guardian_id,dueAt:f.due_at,contactEventId:f.contact_event_id})), teacherNotes:(data.teacherNotes||[]).map(normalizeTeacherNote), aiContactBriefs:aiBriefs };
}
async function refreshData(){ const firstLoad=state.loading; state.error=null; if(firstLoad) render(); try { const data=await loadContactLoopData(); if(data.setupRequired){state.loading=false;state.error='setup';return render();} Object.assign(state,normalizeData(data),{loading:false,error:null}); render(); } catch(error){ console.error(error); state.loading=false; state.error=error.message||'Unable to load Supabase data.'; render(); } }
async function syncCallAndRefresh(eventId=null){ if(callPollingInFlight)return;callPollingInFlight=true;try{await getTelephonyProvider().syncCallStatus(eventId);await refreshData();}catch(error){console.warn('Call status sync is temporarily unavailable.',error);}finally{callPollingInFlight=false;} }
function beginCallPolling(eventId){ if(TELEPHONY_PROVIDER!=='twilio') return; clearInterval(callPollingTimer); window.setTimeout(()=>syncCallAndRefresh(eventId),1500); callPollingTimer=setInterval(()=>syncCallAndRefresh(eventId),3000); window.setTimeout(()=>{clearInterval(callPollingTimer);callPollingTimer=null;},300000); }
async function startRealCall(id,plannedTopic=null){ if(callStartInFlight)return;callStartInFlight=true;try { state.selectedStudentId=id; const provider=getTelephonyProvider(); const call=await provider.startCall(id,{plannedTopic}); state.screen='detail'; await refreshData(); beginCallPolling(call.eventId); } catch(error) { setActionError(error,'Unable to start the call.'); } finally { callStartInFlight=false; } }
function handleCallClick(id){ return openCallFlow(id); }

function statusClass(result){ return result.toLowerCase().replace(' ','-'); }
function renderNav(){ return navItems.map(([id,label])=>`<button class="${state.screen===id?'active':''}" data-nav="${id}"><svg viewBox="0 0 24 24">${icon(id)}</svg><span>${label}</span></button>`).join(''); }

function homeEntryActions(){
  const entry=homeEntryForMode();
  const secondary=entry.secondaryAction?`<button class="button-secondary hero-secondary-cta" data-action="${entry.secondaryAction}">${entry.secondaryLabel}</button>`:'';
  const note=entry.primaryAction==='demo'?'No setup. No call log digging.':'Private workspace for your team.';
  return `<div class="hero-actions ${entry.secondaryAction?'hero-actions-account':''}"><button class="button-primary hero-cta" data-action="${entry.primaryAction}">${entry.primaryLabel} <span>→</span></button>${secondary}<span class="hero-note">${note}</span></div>`;
}
function avatar(s, cls='avatar'){ return `<div class="${cls}">${escapeHtml(s.initials)}</div>`; }
function currentProfile(){ return teacherProfile({ session: state.auth.session }); }
function setActionError(error, fallback){ state.actionError=(error&&error.message)||fallback||'Something went wrong. Please try again.'; render(); }
function actionErrorBanner(){ return state.actionError?`<div class="action-error-banner" role="alert"><span>${escapeHtml(state.actionError)}</span><button type="button" aria-label="Dismiss error" data-dismiss-action-error>×</button></div>`:''; }

function homeScreen(){ const profile=currentProfile(); const heroFirstName=profile.name.split(' ')[0]; return `<div class="home-page"><header class="home-nav"><button class="home-brand" data-home><span class="brand-mark">C</span><span>Contact<span>Loop</span></span></button><div class="home-nav-links"><a href="#how-it-works">How it works</a><a href="#privacy">Privacy first</a></div></header><main class="hero"><div class="hero-copy"><p class="eyebrow">Built for special education teams</p><h1>Every contact,<br><em>automatically tracked.</em></h1><p class="hero-subhead">Automatically track parent calls, outcomes, and follow-ups for special education teams.</p>${homeEntryActions()}</div><div class="hero-visual"><div class="hero-orbit orbit-one"><span>CONTACT</span></div><div class="hero-orbit orbit-two"><span>FOLLOW-UP</span></div><div class="loop-spark spark-one"></div><div class="loop-spark spark-two"></div><div class="browser-window"><div class="browser-bar"><span class="browser-dots"><i></i><i></i><i></i></span><span class="browser-url">app.contactloop.co / dashboard</span><span>•••</span></div><div class="browser-body"><div class="browser-brand">Contact<span>Loop</span></div><div class="browser-greeting"><span>TUESDAY, AUG 25</span><strong>Good morning, ${escapeHtml(heroFirstName)}<span>.</span></strong></div><div class="browser-stats"><div><small>CALLS</small><b>4</b></div><div><small>CONNECTED</small><b>2</b></div><div><small>NO ANSWER</small><b>2</b></div></div><div class="browser-activity"><small>RECENT ACTIVITY</small><div>${avatar({initials:'EJ'},'mini-avatar')}<span><strong>Emma Johnson</strong><em>No answer · Attempt #3</em></span><b>Follow up</b></div><div>${avatar({initials:'LS'},'mini-avatar')}<span><strong>Lucas Smith</strong><em>Connected · 7m 43s</em></span><b class="done">Done</b></div></div></div></div><div class="hero-float"><span class="float-check">✓</span><div><strong>Call documented</strong><small>Emma Johnson · No Answer</small><small>Follow-up scheduled for tomorrow</small></div></div></div></main><section class="home-proof" id="how-it-works"><div><span class="proof-number">01</span><strong>Call from ContactLoop</strong><p>One tap starts the conversation with the right family.</p></div><div><span class="proof-number">02</span><strong>Outcome captured automatically</strong><p>Connected, no answer, busy, or failed — no manual log.</p></div><div><span class="proof-number">03</span><strong>Follow-ups stay visible</strong><p>Never lose track of who needs another contact attempt.</p></div></section><section class="privacy-strip" id="privacy"><span>PRIVATE BY DESIGN</span><p>No call recordings. No transcripts. Just the contact data your team needs.</p></section></div>`; }

function dashboard(){
  const dashboardDate = formatDashboardDate();
  const profile = currentProfile();
  const greeting = greetingForDate();
  const firstName = profile.name.split(' ')[0];
  const filteredEvents=filterEventsByRange(state.events,state.dashboardRange);
  const insights=getDashboardInsights({events:state.events,students:state.students,followUps:state.followUps,range:state.dashboardRange});
  const recent=newestContactEventsFirst(filteredEvents.filter(e=>['Connected','No Answer','Busy','Failed'].includes(e.result))).slice(0,5);
  const customRangeInvalid=state.dashboardRange.preset==='custom'&&state.dashboardRange.from&&state.dashboardRange.to&&state.dashboardRange.from>state.dashboardRange.to;
  const followUpCount=insights.needsFollowUp.length;
  const followUpMessage=`${followUpCount} follow-up${followUpCount===1?'':'s'} need${followUpCount===1?'s':''} your attention today.`;
  const onboarding=state.students.length===0?'<div class="dashboard-onboarding"><div><p class="eyebrow">Start here</p><h2>Set up ContactLoop</h2><p>Import your student and guardian list to start tracking parent communication.</p></div><button class="button-primary" data-action="import-students">Import students <span>→</span></button></div>':'';
  const brief=insights.weekBrief;
  const topics=brief.topTopics.length?brief.topTopics.map(topic=>`<span class="topic-chip">${topic.label}<b>${topic.count}</b></span>`).join(''):'<span class="brief-muted">No topics captured yet.</span>';
  return `<div class="topbar"><div><p class="eyebrow">${dashboardDate}</p><h1>${greeting}, ${escapeHtml(firstName)}<span style="color:var(--coral)">.</span></h1><p class="subhead">${followUpMessage}</p></div><div class="topbar-actions"><div class="dashboard-range"><label for="dashboard-range">View</label><select id="dashboard-range"><option value="today" ${state.dashboardRange.preset==='today'?'selected':''}>Today</option><option value="yesterday" ${state.dashboardRange.preset==='yesterday'?'selected':''}>Yesterday</option><option value="this-week" ${state.dashboardRange.preset==='this-week'?'selected':''}>This week</option><option value="this-month" ${state.dashboardRange.preset==='this-month'?'selected':''}>This month</option><option value="this-year" ${state.dashboardRange.preset==='this-year'?'selected':''}>This year</option><option value="custom" ${state.dashboardRange.preset==='custom'?'selected':''}>Custom</option></select><span class="range-label">${escapeHtml(rangeLabel(state.dashboardRange))}</span>${state.dashboardRange.preset==='custom'?`<div class="custom-range"><label>From <input id="dashboard-from" type="date" value="${state.dashboardRange.from}"></label><label>To <input id="dashboard-to" type="date" value="${state.dashboardRange.to}"></label></div>${customRangeInvalid?'<small class="range-error">From must be before To.</small>':''}`:''}</div><button class="button-primary call-parent-top" data-action="call-parent">+ Call Parent</button><div class="profile">${avatar({initials:profile.initials})}<div><strong>${escapeHtml(profile.name)}</strong><span>${escapeHtml(profile.subtitle)}</span></div></div></div></div>
    ${onboarding}<div class="metric-grid">${[['Call Attempts',insights.metrics.callAttempts,'↗','coral'],['Connected',insights.metrics.connected,'✓','mint'],['Unsuccessful',insights.metrics.unsuccessful,'–','amber'],['Follow-ups Due',insights.metrics.followUpsDue,'!','blue']].map(x=>`<div class="metric"><div class="metric-top"><span>${x[0]}</span><span class="metric-icon ${x[3]}">${x[2]}</span></div><div class="metric-value">${x[1]}</div></div>`).join('')}</div>
    ${SHOW_DEMO_GUIDE?'<div class="demo-guide"><div class="guide-kicker"><span class="guide-pulse"></span>Demo mode</div><div><h2>See the magic in one call.</h2><p>Try the core loop: make a call, choose an outcome, and watch the dashboard update itself.</p></div><button class="button-primary" data-action="try-emma">Call Emma’s mom <span>→</span></button></div>':''}
    <div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Needs Follow-up</h2><span>${followUpCount} open item${followUpCount===1?'':'s'}</span></div>${insights.needsFollowUp.slice(0,5).map(item=>`<div class="attention-item"><span class="attention-dot"></span>${avatar(item.student,'mini-avatar')}<div><h3>${escapeHtml(item.student.name)}</h3><p>${escapeHtml(item.label)}</p></div><button class="attention-action" data-call="${item.student.id}">${escapeHtml(item.actionLabel)}</button></div>`).join('')||'<div class="empty-state">You’re all caught up.</div>'}</section>
    <section class="panel brief-panel"><div class="panel-head"><h2>This Week</h2><span>Contact brief</span></div><div class="brief-body"><div class="brief-stat"><span>Total call attempts</span><strong>${brief.totalAttempts}</strong></div><div class="brief-stat"><span>Successful contacts</span><strong>${brief.successfulContacts}</strong></div><div class="brief-stat"><span>Students needing follow-up</span><strong>${brief.studentsNeedingFollowUp}</strong></div><div class="brief-topics"><span class="brief-label">Top topics</span><div class="topic-list">${topics}</div></div></div></section>
    <section class="panel activity"><div class="panel-head"><h2>Recent Activity</h2><button class="button-secondary" style="width:auto;padding:7px 11px" data-nav="log">View all</button></div>${activityTable(recent)}</section></div>`;
}

function activityTable(events){ return `<div class="table-wrap"><table><thead><tr><th>Student</th><th>Parent</th><th>When</th><th>Result</th><th>Duration</th><th>Attempt</th></tr></thead><tbody>${events.map(e=>{const s=eventStudent(e);return `<tr><td><div class="student-cell">${avatar(s,'mini-avatar')}<span>${escapeHtml(s.name)}</span></div></td><td class="secondary">${escapeHtml(s.relation)}</td><td class="mono secondary">${escapeHtml(e.time)}</td><td><span class="status ${statusClass(e.result)}">${escapeHtml(e.result)}</span></td><td class="mono">${escapeHtml(e.duration||'—')}</td><td class="mono">#${escapeHtml(e.attemptNumber)}</td></tr>`}).join('')}</tbody></table></div>`; }
function contactLogTable(events){ return `<div class="table-wrap"><table class="contact-log-table"><thead><tr><th>Student</th><th>Parent</th><th>When</th><th>Outcome</th><th>Duration</th><th>Planned topic</th><th>Discussed topics</th><th>Attempt</th></tr></thead><tbody>${events.map(e=>{const s=eventStudent(e);return `<tr class="log-row" tabindex="0" data-log-event="${escapeHtml(e.id)}"><td><div class="student-cell">${avatar(s,'mini-avatar')}<span>${escapeHtml(s.name)}</span></div></td><td class="secondary">${escapeHtml(s.relation)}</td><td class="mono secondary">${escapeHtml(e.time)}</td><td><span class="status ${statusClass(e.result)}">${escapeHtml(e.result)}</span></td><td class="mono">${escapeHtml(e.duration||'—')}</td><td>${escapeHtml(e.plannedTopic||'—')}</td><td>${escapeHtml(e.result==='Connected'?discussedTopicsForEvent(e).join(', '):'—')}</td><td class="mono">#${escapeHtml(e.attemptNumber)}</td></tr>`}).join('')||'<tr><td colspan="8" class="log-empty">No contact records match these filters.</td></tr>'}</tbody></table></div>`; }
function studentsScreen(){
  const matches=filterStudents(state.students,state.studentSearch);
  if(!state.students.length)return `<div class="screen-title"><div><p class="eyebrow">Your caseload</p><h1>Students</h1><p class="subhead">Your students and their guardian contacts.</p></div><button class="button-secondary import-header-button" data-action="import-students">Import Students</button></div><section class="students-empty panel"><div class="empty-orb">+</div><h2>Add your students to get started</h2><p>Import a spreadsheet or add students manually.</p><div class="empty-actions"><button class="button-primary" data-action="import-students">Import CSV / Excel</button><button class="button-secondary" data-action="new-student">Add student manually</button></div></section>`;
  return `<div class="screen-title"><div><p class="eyebrow">Your caseload</p><h1>Students</h1><p class="subhead">${state.students.length} students · click a card to see contact history.</p></div><div class="student-header-actions"><button class="button-secondary" data-action="new-student">+ Add Student</button><button class="button-primary" data-action="import-students">Import Students</button></div></div><div class="student-page-search"><span>⌕</span><input id="student-page-search" type="search" value="${escapeHtml(state.studentSearch)}" placeholder="Search students, parents, or phone numbers…" aria-label="Search students, parents, or phone numbers"></div><div class="student-grid">${matches.map(s=>{const latest=newestContactEventsFirst(state.events.filter(e=>e.studentId===s.id))[0];const menuOpen=state.studentMenuId===s.id;return `<article class="student-card"><div class="student-card-top">${avatar(s)}<div class="student-card-actions"><span class="status ${latest?.result==='Connected'?'connected':'no-answer'}">${latest?.result==='Connected'?'On track':'Needs follow-up'}</span><button type="button" class="student-menu-toggle" aria-label="Student actions" aria-expanded="${menuOpen}" data-action="toggle-student-menu" data-student-id="${escapeHtml(s.id)}">•••</button><div class="student-card-menu ${menuOpen?'open':''}" data-student-menu="${escapeHtml(s.id)}"><button type="button" data-action="edit-student" data-student-id="${escapeHtml(s.id)}">Edit student</button><button type="button" data-action="delete-student" data-student-id="${escapeHtml(s.id)}">Delete student</button></div></div></div><h2>${escapeHtml(s.name)}</h2><p>${escapeHtml(s.relation)} · ${escapeHtml(s.parent)}<br>${escapeHtml(s.phone)}</p><div class="card-meta"><strong>${state.events.filter(e=>e.studentId===s.id).length}</strong> contact events · Last ${latest?.time||'not contacted'}</div><button class="button-secondary" data-student="${escapeHtml(s.id)}">View contact history</button></article>`}).join('')||'<div class="panel empty-state student-search-empty">No students match your search.</div>'}</div>`;
}
function contactSummaryRange(events){const times=events.map(event=>new Date(event.callTime).getTime()).filter(Number.isFinite);const from=times.length?new Date(Math.min(...times)).toISOString():new Date(Date.now()-30*86400000).toISOString();const to=new Date(Date.now()+86400000).toISOString();return {from,to};}
function aiSummaryFields(){return [['key_topics','Key topics'],['parent_concerns','Parent concerns'],['recorded_resolutions','Recorded resolutions'],['open_items','Open items']];}
function beginAiSummaryEdit(id){const result=state.aiContactBriefs[id];if(!result?.brief)return;result.editing=true;result.editor=createEditableBrief(result.brief);render();}
function renderAiSummaryEdit(id,result){const editor=result.editor||createEditableBrief(result.brief);result.editor=editor;const fields=aiSummaryFields().map(([field,label])=>`<div class="ai-summary-edit-section"><label>${label}</label><div class="ai-edit-list">${editor.brief[field].map((item,index)=>`<div class="ai-edit-row"><input data-ai-item="${field}" data-ai-index="${index}" value="${escapeHtml(item)}"><button type="button" aria-label="Delete ${label} item" data-ai-delete="${field}:${index}">Delete</button></div>`).join('')}</div><button type="button" class="ai-add-item" data-ai-add="${field}">+ Add ${label.toLowerCase().replace(/s$/,'')}</button></div>`).join('');return `<div class="ai-summary-edit-form">${fields}<div class="ai-summary-edit-section"><label for="ai-next-step">Suggested next step</label><textarea id="ai-next-step" data-ai-next-step>${escapeHtml(editor.brief.suggested_next_step)}</textarea></div><div class="ai-summary-actions"><button class="button-secondary" data-ai-cancel="${id}">Cancel</button><button class="button-primary" data-ai-save="${id}">Save changes</button></div></div>`;}
function renderAiContactSummary(id){const s=student(id);const events=state.events.filter(event=>event.studentId===id);const stats=buildContactSummaryStats({studentId:id,events,followUps:state.followUps});const result=state.aiContactBriefs[id];const lists=result?.brief?[['Key topics',result.brief.key_topics],['Parent concerns',result.brief.parent_concerns],['Recorded resolutions',result.brief.recorded_resolutions],['Open items',result.brief.open_items]].map(([label,items])=>`<div class="ai-summary-section"><span>${label}</span>${items?.length?`<ul>${items.map(item=>`<li>${escapeHtml(item)}</li>`).join('')}</ul>`:'<p>No confirmed information recorded.</p>'}</div>`).join(''):'';const approveAction=result?.status==='approved'?'<span class="ai-summary-approved">✓ Teacher Approved</span>':`<button class="button-primary" data-ai-approve="${id}">Approve summary</button>`;const content=result?.editing?renderAiSummaryEdit(id,result):result?.brief?`<div class="ai-review-badge">${result.status==='approved'?'Teacher Approved':'Needs teacher review'}</div>${lists}<div class="ai-next-step"><span>Suggested next step</span><p>${escapeHtml(result.brief.suggested_next_step||'No suggested next step recorded.')}</p></div><div class="ai-summary-actions"><button class="button-secondary" data-ai-edit="${id}">Edit</button>${approveAction}<div class="ai-menu-wrap"><button class="button-secondary ai-menu-button" aria-label="More summary actions" data-ai-menu-toggle="${id}">•••</button><div class="ai-menu" data-ai-menu="${id}"><button data-ai-regenerate="${id}">Regenerate summary</button><button data-ai-remove="${id}">Remove summary</button></div></div></div>`:result?.loading?'':`<p class="ai-summary-empty">Summarize the recorded topics, teacher notes, and open follow-ups for ${escapeHtml(s?.name||'this student')}.</p><button class="button-primary ai-generate-button" data-ai-generate="${id}" ${aiContactBriefEnabled?'':'disabled'}>${aiContactBriefEnabled?'Generate summary':'AI provider not configured'}</button>`;return `<aside class="ai-summary-card"><div class="ai-summary-header"><div><p class="eyebrow">AI-assisted, teacher-controlled</p><h2>AI Contact Summary</h2></div><span class="ai-summary-spark">✦</span></div><div class="ai-summary-stats"><div><strong>${stats.attempts}</strong><span>Attempts</span></div><div><strong>${stats.connected}</strong><span>Connected</span></div><div><strong>${stats.unsuccessful}</strong><span>Unsuccessful</span></div><div><strong>${stats.openFollowUps}</strong><span>Open follow-up</span></div></div>${result?.loading?'<p class="ai-summary-empty">Reading confirmed contact context…</p>':''}${result?.error?`<div class="ai-summary-error">${escapeHtml(result.error)}</div>`:''}${content}</aside>`;}
async function generateAiContactSummary(id){if(!aiContactBriefEnabled)return;const events=state.events.filter(event=>event.studentId===id);const range=contactSummaryRange(events);const previous=state.aiContactBriefs[id];state.aiContactBriefs[id]={loading:true};render();try{const result=await contactBriefProvider.generate({studentId:id,dateFrom:range.from,dateTo:range.to,includeNotes:true});const version=(previous?.version||0)+1;const saved=await saveAiContactBrief({studentId:id,dateFrom:range.from,dateTo:range.to,version,status:'draft',brief:result.brief});if(previous?.id)await supersedeAiContactBrief(previous.id);state.aiContactBriefs[id]={...result,...saved,loading:false,status:'draft',version:saved.version};}catch(error){state.aiContactBriefs[id]={...previous,error:error.message||'Unable to generate AI summary.',loading:false};}render();}
async function saveAiSummaryEdits(id){const result=state.aiContactBriefs[id];if(!result?.editor)return;try{const plan=summaryEditPlan(result);const events=state.events.filter(event=>event.studentId===id);const range=contactSummaryRange(events);let saved;if(plan.mode==='new-version'){saved=await saveAiContactBrief({studentId:id,dateFrom:range.from,dateTo:range.to,version:plan.version,status:'draft',brief:result.editor.brief});await supersedeAiContactBrief(plan.previousId);}else if(plan.mode==='update'){saved=await updateAiContactBrief(plan.id,{brief:result.editor.brief,status:'draft'});}else{saved=await saveAiContactBrief({studentId:id,dateFrom:range.from,dateTo:range.to,version:plan.version,status:'draft',brief:result.editor.brief});}state.aiContactBriefs[id]={...result,brief:result.editor.brief,id:saved.id,version:saved.version,status:'draft',editing:false,editor:null,error:null};render();}catch(error){result.error=error.message||'Unable to save summary changes.';render();}}
function cancelAiSummaryEdit(id){const result=state.aiContactBriefs[id];if(!result)return;result.editor=cancelBriefEdits(result.editor||createEditableBrief(result.brief));result.editing=false;render();}
async function approveAiSummary(id){const result=state.aiContactBriefs[id];if(!result)return;try{if(result.id)await approveAiContactBrief(result.id);result.status='approved';result.approved=true;render();}catch(error){result.error=error.message||'Unable to approve summary.';render();}}
async function removeAiSummary(id){const result=state.aiContactBriefs[id];try{if(result?.id)await removeAiContactBrief(result.id);delete state.aiContactBriefs[id];render();}catch(error){result.error=error.message||'Unable to remove summary.';render();}}
function openVoiceNote(id){state.selectedStudentId=id;state.voiceNote=createVoiceNoteState();state.modal={step:'voice'};renderModal();if(APP_MODE==='demo')startDemoVoiceRecording();else startVoiceRecording();}
function startDemoVoiceRecording(){const voice=state.voiceNote;if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){state.voiceNote=createDemoVoiceNote();return renderModal();}navigator.mediaDevices.getUserMedia({audio:true}).then(stream=>{const chunks=[];const recorder=new MediaRecorder(stream);state.voiceNote={...voice,status:'recording',recorder,elapsedSeconds:0,chunks,error:null};recorder.ondataavailable=event=>chunks.push(event.data);recorder.onstop=()=>{stream.getTracks().forEach(track=>track.stop());if(state.voiceNote.timer)clearInterval(state.voiceNote.timer);state.voiceNote={...createDemoVoiceNote(),recorder:null,timer:null};renderModal();};recorder.start();state.voiceNote.timer=setInterval(()=>{state.voiceNote.elapsedSeconds+=1;renderModal();},1000);renderModal();}).catch(()=>{state.voiceNote=createDemoVoiceNote();renderModal();});}
function closeVoiceNote(){if(state.voiceNote.recorder?.state==='recording')state.voiceNote.recorder.stop();if(state.voiceNote.timer)clearInterval(state.voiceNote.timer);state.modal=null;state.voiceNote=createVoiceNoteState();document.querySelector('#modal-root').innerHTML='';}
function renderVoiceModal(){const voice=state.voiceNote;const busy=['uploading','transcribing','saving'].includes(voice.status);let body='';if(voice.status==='idle')body='<p class="voice-help">Record a short note to add context to this student’s communication history.</p><button class="button-primary" data-voice-start>Start recording</button>';if(voice.status==='recording')body=`<div class="voice-timer">${String(Math.floor(voice.elapsedSeconds/60)).padStart(2,'0')}:${String(voice.elapsedSeconds%60).padStart(2,'0')}</div><button class="button-primary" data-voice-stop>Stop</button>`;if(voice.status==='uploading')body='<p class="voice-progress">Uploading…</p>';if(voice.status==='transcribing')body='<p class="voice-progress">Transcribing…</p>';if(voice.status==='review')body=`<label class="modal-label" for="voice-transcript">Voice transcript</label><textarea id="voice-transcript" class="voice-transcript">${escapeHtml(voice.transcript)}</textarea><button class="button-primary" data-voice-save>Save note</button>`;if(voice.status==='error')body=`<div class="ai-summary-error">${escapeHtml(voice.error)}</div><button class="button-secondary" data-voice-retry>Try again</button>`;return `<div class="modal-backdrop"><div class="modal voice-modal"><div class="modal-header"><div><p class="eyebrow">Teacher context</p><h2>Add context by voice</h2><p>Record a short note to add context to this student's communication history.</p></div><button class="close" data-voice-cancel>×</button></div><div class="voice-body">${body}</div>${!busy&&voice.status!=='review'?'<div class="modal-footer"><button class="button-cancel" data-voice-cancel>Cancel</button></div>':''}</div></div>`;}
async function pollVoiceTranscript(studentId,jobId){state.voiceNote.status='transcribing';renderModal();try{for(let attempt=0;attempt<30;attempt+=1){const result=await getVoiceTranscriptStatus({studentId,jobId,objectKey:state.voiceNote.objectKey});if(result.status==='completed'){const transcript=(result.transcript||'').trim();if(!transcript)throw new Error('No speech detected. Please record a little longer and speak clearly.');state.voiceNote.status='review';state.voiceNote.transcript=transcript;return renderModal();}if(result.status==='failed')throw new Error('Transcription failed. Please try recording again.');await new Promise(resolve=>setTimeout(resolve,2000));}throw new Error('Transcription timed out. Please try again.');}catch(error){state.voiceNote=voiceNoteError(edgeFunctionError(error,'Voice note service'));renderModal();}}
async function stopVoiceRecording(){const voice=state.voiceNote;const recorder=voice.recorder;if(!recorder)return;recorder.stop();}
function startVoiceRecording(){const voice=state.voiceNote;if(!['idle','error'].includes(voice.status))return;if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){state.voiceNote=voiceNoteError('Voice recording is not supported in this browser.');return renderModal();}navigator.mediaDevices.getUserMedia({audio:true}).then(stream=>{const chunks=[];const recorder=new MediaRecorder(stream);state.voiceNote={...state.voiceNote,status:'recording',recorder,elapsedSeconds:0,chunks,error:null};recorder.ondataavailable=event=>chunks.push(event.data);recorder.onstop=async()=>{stream.getTracks().forEach(track=>track.stop());if(state.voiceNote.timer)clearInterval(state.voiceNote.timer);state.voiceNote={...state.voiceNote,status:'uploading',recorder:null,timer:null};renderModal();try{const blob=new Blob(chunks,{type:recorder.mimeType||'audio/webm'});const upload=await createVoiceUpload({studentId:state.selectedStudentId,contentType:blob.type});const uploaded=await fetch(upload.uploadUrl,{method:'PUT',headers:{'Content-Type':blob.type},body:blob});if(!uploaded.ok)throw new Error(`Audio upload failed (${uploaded.status}).`);const job=await startVoiceTranscription({studentId:state.selectedStudentId,objectKey:upload.objectKey});if(!job?.jobId)throw new Error('Transcription did not return a job id.');state.voiceNote.objectKey=upload.objectKey;await pollVoiceTranscript(state.selectedStudentId,job.jobId);}catch(error){state.voiceNote=voiceNoteError(edgeFunctionError(error,'Voice note service'));renderModal();}};recorder.start();state.voiceNote.timer=setInterval(()=>{state.voiceNote.elapsedSeconds+=1;renderModal();},1000);renderModal();}).catch(error=>{state.voiceNote=voiceNoteError(error.message||'Microphone permission was denied.');renderModal();});}
function renderContextSavedNotice(studentId){const card=document.querySelector('.ai-summary-card');if(!card)return;const actions=card.querySelector('.ai-summary-actions');const generate=card.querySelector('[data-ai-generate]');const target=actions||generate;if(!target)return;const message=contextSavedMessage(aiContactBriefEnabled);const notice=document.createElement('div');notice.className='ai-context-saved';notice.innerHTML=`<strong>${escapeHtml(message.title)}</strong><span>${escapeHtml(message.detail)}</span>${message.actionLabel?`<button class="button-secondary" data-ai-update-summary>${escapeHtml(message.actionLabel)}</button>`:''}`;target.parentNode.insertBefore(notice,target);const update=notice.querySelector('[data-ai-update-summary]');if(update)update.onclick=()=>{const result=state.aiContactBriefs[studentId];if(result)result.contextSaved=false;notice.remove();generateAiContactSummary(studentId);};}
async function saveVoiceNote(){const transcript=document.querySelector('#voice-transcript')?.value?.trim();if(!transcript||!canSaveVoiceNote({...state.voiceNote,transcript}))return;const studentId=state.selectedStudentId;if(APP_MODE==='demo'){state.teacherNotes=addDemoTeacherNote(state.teacherNotes,studentId,transcript);closeVoiceNote();render();renderContextSavedNotice(studentId);return;}state.voiceNote.transcript=transcript;state.voiceNote.status='saving';renderModal();try{await createTeacherNote({studentId,content:transcript,source:'voice'});closeVoiceNote();await refreshData();const brief=state.aiContactBriefs[studentId];state.aiContactBriefs[studentId]={...brief,contextSaved:true};render();renderContextSavedNotice(studentId);}catch(error){state.voiceNote=voiceNoteError(error.message||'Unable to save note.');renderModal();}}
function openTeacherNote(id){state.selectedStudentId=id;state.modal={step:'teacher-note',content:'',error:null,saving:false,editingNoteId:null};renderModal();}
function openEditTeacherNote(noteId){const note=state.teacherNotes.find(item=>item.id===noteId);if(!note)return;state.selectedStudentId=note.studentId??note.student_id;state.modal={step:'teacher-note',content:note.content,error:null,saving:false,editingNoteId:note.id};renderModal();}
function closeTeacherNote(){state.modal=null;document.querySelector('#modal-root').innerHTML='';}
function isLocalDemoNote(note){return typeof note?.id==='string'&&note.id.startsWith('demo-note-');}
async function persistTeacherNoteUpdate(noteId,content){const note=state.teacherNotes.find(item=>item.id===noteId);if(note&&isLocalDemoNote(note)){state.teacherNotes=state.teacherNotes.map(item=>item.id===noteId?{...item,content}:item);return {local:true};}await requireFacadeAction('updateTeacherNote')(noteId,{content});return {local:false};}
async function persistTeacherNoteDelete(noteId){const note=state.teacherNotes.find(item=>item.id===noteId);if(note&&isLocalDemoNote(note)){state.teacherNotes=state.teacherNotes.filter(item=>item.id!==noteId);return {local:true};}await requireFacadeAction('deleteTeacherNote')(noteId);return {local:false};}
function openDeleteTeacherNote(noteId){const note=state.teacherNotes.find(item=>item.id===noteId);if(!note)return;const s=student(note.studentId??note.student_id);openConfirmDialog({title:'Delete teacher note?',body:`This ${teacherNoteSourceLabel(note.source).toLowerCase()} will be permanently removed from ${s?.name||'this student'}’s record. This can’t be undone.`,confirmLabel:'Delete note',action:async()=>{const result=await persistTeacherNoteDelete(noteId);if(!result.local)await refreshData();else render();}});}
function renderTeacherNoteModal(){const m=state.modal;const editing=Boolean(m.editingNoteId);const s=student(state.selectedStudentId);return `<div class="modal-backdrop"><div class="modal teacher-note-modal"><div class="modal-header"><div><p class="eyebrow">Teacher context</p><h2>${editing?'Edit teacher note':'Add a teacher note'}</h2><p>Write a short, confirmed note about ${escapeHtml(s?.name||'this student')}.</p></div><button class="close" data-teacher-note-cancel>×</button></div>${m.error?`<div class="ai-summary-error">${escapeHtml(m.error)}</div>`:''}<label class="modal-label" for="teacher-note-input">Note · teacher confirmed</label><textarea id="teacher-note-input" class="teacher-note-input" placeholder="e.g. Parent asked about homework and confirmed Friday’s meeting.">${escapeHtml(m.content||'')}</textarea><div class="modal-footer"><button class="button-cancel" data-teacher-note-cancel>Cancel</button><button class="button-primary" data-teacher-note-save ${m.saving||!m.content?.trim()?'disabled':''}>${editing?'Save changes':'Save note'}</button></div></div></div>`;}
function bindTeacherNoteModalEvents(){document.querySelectorAll('[data-teacher-note-cancel]').forEach(button=>button.onclick=closeTeacherNote);const input=document.querySelector('#teacher-note-input');if(input)input.oninput=()=>{state.modal.content=input.value;const save=document.querySelector('[data-teacher-note-save]');if(save)save.disabled=!input.value.trim()||state.modal.saving;};document.querySelector('[data-teacher-note-save]')?.addEventListener('click',saveTypedTeacherNote);}
async function saveTypedTeacherNote(){const m=state.modal;const content=m?.content?.trim();if(!content||m.saving)return;const studentId=state.selectedStudentId;m.saving=true;m.error=null;renderModal();try{const editing=Boolean(m.editingNoteId);if(editing){const result=await persistTeacherNoteUpdate(m.editingNoteId,content);closeTeacherNote();if(result.local){render();return;}}else{await createTeacherNote({studentId,content,source:'typed'});}closeTeacherNote();await refreshData();const brief=state.aiContactBriefs[studentId];state.aiContactBriefs[studentId]={...brief,contextSaved:true};render();renderContextSavedNotice(studentId);}catch(error){state.modal={...m,saving:false,error:error.message||'Unable to save note.'};renderModal();}}
function openAiItemDialog(field){state.modal=createAiItemDialogState(field);document.querySelector('#modal-root').innerHTML=renderAiItemDialog();bindAiItemDialogEvents();}
function closeAiItemDialog(){state.modal=null;document.querySelector('#modal-root').innerHTML='';}
function renderAiItemDialog(){const m=state.modal;const label=aiItemLabel(m.field);return `<div class="modal-backdrop"><div class="modal ai-item-modal"><div class="modal-header"><div><p class="eyebrow">Edit summary</p><h2>Add ${escapeHtml(label.toLowerCase())}</h2><p>Add one teacher-confirmed item to this AI Contact Summary.</p></div><button class="close" data-ai-item-cancel>×</button></div><label class="modal-label" for="ai-item-input">${escapeHtml(label)}</label><textarea id="ai-item-input" class="ai-item-input" placeholder="Write a concise, confirmed item…">${escapeHtml(m.value||'')}</textarea><div class="modal-footer"><button class="button-cancel" data-ai-item-cancel>Cancel</button><button class="button-primary" data-ai-item-save ${!m.value?.trim()?'disabled':''}>Add item</button></div></div></div>`;}
function bindAiItemDialogEvents(){document.querySelectorAll('[data-ai-item-cancel]').forEach(button=>button.onclick=closeAiItemDialog);const input=document.querySelector('#ai-item-input');if(input)input.oninput=()=>{state.modal.value=input.value;const save=document.querySelector('[data-ai-item-save]');if(save)save.disabled=!input.value.trim();};document.querySelector('[data-ai-item-save]')?.addEventListener('click',saveAiItemDialog);input?.focus();}
function saveAiItemDialog(){const m=state.modal;const value=m?.value?.trim();if(!value)return;const result=state.aiContactBriefs[state.selectedStudentId];if(!result?.editor){closeAiItemDialog();return;}result.editor=addBriefItem(result.editor,m.field,value);closeAiItemDialog();render();}
function renderTeacherNotes(id){const notes=notesForStudent(state.teacherNotes,id);return `<section class="teacher-notes-card"><div class="teacher-notes-head"><div><p class="eyebrow">Your confirmed context</p><h2>Teacher Notes</h2><p>Notes you add here stay separate from the AI summary until you choose to update it.</p></div><div class="teacher-notes-actions"><button class="button-secondary" data-add-teacher-note="${escapeHtml(id)}">+ Add note</button><button class="button-secondary" data-add-teacher-voice="${escapeHtml(id)}">🎤 Voice</button></div></div>${notes.length?`<div class="teacher-notes-list">${notes.map(note=>`<article class="teacher-note"><div><div class="teacher-note-meta"><strong>${escapeHtml(teacherNoteSourceLabel(note.source))}</strong><span>${escapeHtml(formatEventTime(note.createdAt))}</span></div><div class="teacher-note-actions"><button type="button" class="teacher-note-action" data-edit-teacher-note="${escapeHtml(note.id)}">Edit</button><button type="button" class="teacher-note-action danger" data-delete-teacher-note="${escapeHtml(note.id)}">Delete</button></div></div><p>${escapeHtml(note.content)}</p></article>`).join('')}</div>`:'<div class="teacher-notes-empty">No teacher notes yet. Add typed or voice context after a call.</div>'}</section>`;}
function renderGuardians(s){const guardians=s.guardians||[];return `<section class="panel guardians-card"><div class="panel-head"><h2>Guardians</h2><button class="button-secondary guardian-add" data-add-guardian="${escapeHtml(s.id)}">+ Add guardian</button></div>${guardians.length?`<div class="guardian-roster">${guardians.map(guardian=>`<div class="guardian-row"><div class="guardian-row-main"><strong>${escapeHtml(guardian.name||'Guardian')}</strong><span>${escapeHtml(guardian.relation||'Guardian')}${guardian.phone?` · ${escapeHtml(guardian.phone)}`:''}</span></div><div class="guardian-row-actions"><button type="button" class="guardian-action" data-edit-guardian="${escapeHtml(guardian.id)}">Edit</button><button type="button" class="guardian-action danger" data-remove-guardian="${escapeHtml(guardian.id)}">Delete</button></div></div>`).join('')}</div>`:'<div class="empty-state">No guardians on file yet. Add a guardian to start contacting families.</div>'}</section>`;}
function detailScreen(id){const s=student(id);const events=newestContactEventsFirst(state.events.filter(e=>e.studentId===id));const open=events.find(e=>e.followUp);return `<button class="back" data-nav="students">← Back to students</button><div class="detail-head">${avatar(s)}<div><h1>${escapeHtml(s.name)}</h1><p>${escapeHtml(s.relation)} · ${escapeHtml(s.parent)} · ${escapeHtml(s.phone)}</p></div><div class="detail-actions"><button class="button-primary" data-call="${escapeHtml(s.id)}" ${s.guardianId?'':'disabled'}>Call ${escapeHtml(s.relation)}</button></div></div><div class="detail-layout"><div>${renderGuardians(s)}<div class="history"><div class="panel-head" style="padding-left:0;padding-right:0;border-bottom:0"><h2>Contact history</h2><span>${events.length} event${events.length===1?'':'s'}</span></div>${events.length?events.map(e=>{const topics=eventTopicSummary(e);return `<div class="history-item"><div class="history-time">${e.time.replace(' · ','<br>')}</div><div class="history-marker"></div><div class="history-card"><div class="history-card-top"><h3>Phone call · <span class="status ${statusClass(e.result)}">${escapeHtml(e.result)}</span></h3><span class="mono secondary">Attempt #${escapeHtml(e.attemptNumber)}</span><button type="button" class="history-delete" data-event-delete="${escapeHtml(e.id)}" aria-label="Delete this contact record">Delete</button></div>${e.duration?`<p><strong>${escapeHtml(e.duration)}</strong> conversation</p>`:''}${topics.discussed.length?`<p>Discussed topics: <strong>${escapeHtml(topics.discussed.join(', '))}</strong></p>`:topics.planned?`<p>Planned topic: <strong>${escapeHtml(topics.planned)}</strong></p>`:''}${e.note?`<p class="history-note">“${escapeHtml(e.note)}”</p>`:''}</div></div>`}).join(''):'<div class="empty-state">No contact events yet. Start the first call to build this history.</div>'}</div>${open?`<div class="followup-card"><h3>Follow-up scheduled · ${escapeHtml(open.followUp)}</h3><p>This student will stay on your attention list until the next contact is logged.</p></div>`:''}${renderTeacherNotes(id)}</div>${renderAiContactSummary(id)}</div>`; }
function followupsScreen(){
  const items=buildFollowUpItems({followUps:state.followUps,events:state.events,students:state.students});
  const groups=['TODAY','TOMORROW','UPCOMING'];
  const grouped=groups.map(group=>{const groupItems=items.filter(item=>item.group===group);if(!groupItems.length)return '';return `<section class="followup-group"><div class="followup-group-label">${group}<span>${groupItems.length}</span></div><div class="followup-list">${groupItems.map(item=>`<div class="followup-row">${avatar(item.student)}<div class="followup-main"><h3>${escapeHtml(item.student.name)} · ${escapeHtml(item.student.relation)}</h3><p>${escapeHtml(item.summary)}</p><small>Last attempt: ${escapeHtml(item.lastContact)}</small></div><div class="followup-due"><strong>${escapeHtml(item.nextFollowUp)}</strong></div><button class="button-primary followup-call" data-call="${escapeHtml(item.student.id)}">Call</button><div class="followup-menu-wrap"><button class="followup-menu-button" aria-label="More actions for ${escapeHtml(item.student.name)}" data-followup-menu-toggle="${escapeHtml(item.id)}">•••</button><div class="followup-menu" data-followup-menu="${escapeHtml(item.id)}"><button data-followup-reschedule="${escapeHtml(item.id)}">Reschedule</button><button data-followup-done="${escapeHtml(item.id)}">Mark done</button><button data-followup-dismiss="${escapeHtml(item.id)}">Dismiss follow-up</button><button class="danger" data-followup-delete="${escapeHtml(item.id)}">Delete follow-up</button><button data-followup-history="${escapeHtml(item.student.id)}">View contact history</button></div></div></div>`).join('')}</div></section>`;}).join('');
  return `<div class="screen-title"><div><p class="eyebrow">Keep the loop closed</p><h1>Follow-ups</h1><p class="subhead">${items.length} open follow-up${items.length===1?'':'s'} · Your next contacts, in priority order.</p></div></div>${grouped||'<div class="panel empty-state">No open follow-ups right now. You’re all caught up.</div>'}`;
}
function logScreen(){const f=state.logFilters;const filtered=filterContactLogEvents(state.events,f,state.students);const customInvalid=f.range.preset==='custom'&&f.range.from&&f.range.to&&f.range.from>f.range.to;return `<div class="screen-title"><div><p class="eyebrow">Every touch, accounted for</p><h1>Contact Log</h1><p class="subhead">A complete record of parent communication.</p></div><div class="log-actions"><button class="button-secondary brief-entry" data-action="meeting-brief">Generate Meeting Brief</button><button data-action="export-log">Export Contact Records</button></div></div><div class="log-filters"><label class="log-search"><span>⌕</span><input id="log-search" type="search" value="${escapeHtml(f.search)}" placeholder="Search contacts…" aria-label="Search contacts"></label><label><span>Date range</span><select id="log-range"><option value="today" ${f.range.preset==='today'?'selected':''}>Today</option><option value="this-week" ${f.range.preset==='this-week'?'selected':''}>This Week</option><option value="this-month" ${f.range.preset==='this-month'?'selected':''}>This Month</option><option value="this-year" ${f.range.preset==='this-year'?'selected':''}>This Year</option><option value="custom" ${f.range.preset==='custom'?'selected':''}>Custom</option></select></label><label><span>Outcome</span><select id="log-outcome"><option value="all">All outcomes</option>${['Connected','No Answer','Busy','Failed'].map(value=>`<option value="${value}" ${f.outcome===value?'selected':''}>${value}</option>`).join('')}</select></label><label><span>Student</span><select id="log-student"><option value="all">All students</option>${state.students.map(s=>`<option value="${escapeHtml(s.id)}" ${f.studentId===s.id?'selected':''}>${escapeHtml(s.name)}</option>`).join('')}</select></label>${f.range.preset==='custom'?`<div class="log-custom-range"><label>From <input id="log-from" type="date" value="${f.range.from}"></label><label>To <input id="log-to" type="date" value="${f.range.to}"></label></div>${customInvalid?'<small class="range-error">From must be before To.</small>':''}`:''}</div><section class="panel activity"><div class="panel-head"><h2>Contact records</h2><span>${filtered.length} record${filtered.length===1?'':'s'}</span></div>${contactLogTable(newestContactEventsFirst(filtered))}</section>`;}
function openLogDetail(eventId){const e=state.events.find(event=>event.id===eventId);const s=e&&eventStudent(e);const openFollowUp=e&&state.followUps.find(followUp=>followUp.contactEventId===e.id||followUp.id===e.followUpId);const topics=eventTopicSummary(e);document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal log-detail-modal"><div class="modal-header"><div><p class="eyebrow">Contact record</p><h2>${escapeHtml(s?.name||'Student')} · ${escapeHtml(s?.relation||'Parent')}</h2><p>${escapeHtml(e?.time||'—')}</p></div><button class="close" data-close>×</button></div><div class="log-detail-grid"><div><span>Outcome</span><strong><span class="status ${statusClass(e?.result||'Failed')}">${escapeHtml(e?.result||'—')}</span></strong></div><div><span>Duration</span><strong>${escapeHtml(e?.duration||'—')}</strong></div><div><span>Planned topic</span><strong>${escapeHtml(topics.planned||'—')}</strong></div><div><span>Discussed topics</span><strong>${escapeHtml(topics.discussed.length?topics.discussed.join(', '):'—')}</strong></div><div><span>Attempt</span><strong>#${escapeHtml(e?.attemptNumber||'—')}</strong></div></div><div class="log-detail-copy"><p><b>Teacher-approved note</b><br>${escapeHtml(e?.note||'No teacher-approved note recorded.')}</p><p><b>Follow-up</b><br>${openFollowUp?'Open · '+escapeHtml(followUpLabel(openFollowUp.dueAt||openFollowUp.due_at)):'None'}</p></div><div class="modal-footer log-detail-footer"><button class="button-danger" data-log-event-delete="${escapeHtml(eventId)}">Delete record</button><button class="button-primary" data-close>Done</button></div></div></div>`;document.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>{state.modal=null;document.querySelector('#modal-root').innerHTML=''});document.querySelectorAll('[data-log-event-delete]').forEach(button=>button.onclick=()=>openDeleteContactEvent(button.dataset.logEventDelete));}
function exportFilteredContactLog(){const filtered=filterContactLogEvents(state.events,state.logFilters,state.students);const csv=toContactLogCsv(newestContactEventsFirst(filtered),state.students);const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='contactloop-contact-records.csv';link.click();URL.revokeObjectURL(url);}
function renderMeetingBriefSettings(){const settings=state.meetingSettings;const custom=settings.range.preset==='custom';document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal meeting-settings-modal"><div class="modal-header"><div><p class="eyebrow">Meeting materials</p><h2>Generate Meeting Brief</h2><p>Build a print-friendly summary from teacher-confirmed records.</p></div><button class="close" data-meeting-cancel>×</button></div><div class="form-grid"><label>Student<select id="meeting-student">${state.students.map(s=>`<option value="${escapeHtml(s.id)}" ${settings.studentId===s.id?'selected':''}>${escapeHtml(s.name)}</option>`).join('')}</select></label><label>Date range<select id="meeting-range"><option value="today" ${settings.range.preset==='today'?'selected':''}>Today</option><option value="this-week" ${settings.range.preset==='this-week'?'selected':''}>This Week</option><option value="this-month" ${settings.range.preset==='this-month'?'selected':''}>This Month</option><option value="this-year" ${settings.range.preset==='this-year'?'selected':''}>This Year</option><option value="custom" ${custom?'selected':''}>Custom</option></select></label>${custom?`<label>From<input id="meeting-from" type="date" value="${settings.range.from}"></label><label>To<input id="meeting-to" type="date" value="${settings.range.to}"></label>`:''}</div><div class="meeting-options"><label><input type="checkbox" id="meeting-history" ${settings.includeHistory?'checked':''}> Include detailed contact history</label><label><input type="checkbox" id="meeting-notes" ${settings.includeNotes?'checked':''}> Include teacher-approved notes</label><label class="disabled-option"><input type="checkbox" disabled ${settings.includeAI?'checked':''}> Include AI summary <small>Not connected in this MVP</small></label><label><input type="checkbox" id="meeting-hide-phone" ${settings.hidePhone?'checked':''}> Hide parent phone numbers</label></div><div class="modal-footer"><button class="button-cancel" data-meeting-cancel>Cancel</button><button class="button-primary" data-meeting-generate>Generate brief</button></div></div></div>`;document.querySelectorAll('[data-meeting-cancel]').forEach(button=>button.onclick=()=>{state.meetingSettings=null;document.querySelector('#modal-root').innerHTML=''});const studentInput=document.querySelector('#meeting-student');if(studentInput)studentInput.onchange=()=>{settings.studentId=studentInput.value};const rangeInput=document.querySelector('#meeting-range');if(rangeInput)rangeInput.onchange=()=>{settings.range={preset:rangeInput.value,from:'',to:''};renderMeetingBriefSettings()};const fromInput=document.querySelector('#meeting-from');if(fromInput)fromInput.onchange=()=>{settings.range.from=fromInput.value};const toInput=document.querySelector('#meeting-to');if(toInput)toInput.onchange=()=>{settings.range.to=toInput.value};document.querySelector('#meeting-history')?.addEventListener('change',event=>{settings.includeHistory=event.target.checked});document.querySelector('#meeting-notes')?.addEventListener('change',event=>{settings.includeNotes=event.target.checked});document.querySelector('#meeting-hide-phone')?.addEventListener('change',event=>{settings.hidePhone=event.target.checked});document.querySelector('[data-meeting-generate]')?.addEventListener('click',generateMeetingBrief);}
function openMeetingBriefSettings(){state.meetingSettings={studentId:state.logFilters.studentId!=='all'?state.logFilters.studentId:(state.students[0]?.id||''),range:{...state.logFilters.range},includeHistory:true,includeNotes:true,includeAI:false,hidePhone:true};renderMeetingBriefSettings();}
function generateMeetingBrief(){const settings=state.meetingSettings;state.meetingBrief=buildMeetingBrief({events:state.events,students:state.students,followUps:state.followUps,teacherNotes:state.teacherNotes,includeNotes:settings.includeNotes,studentId:settings.studentId,range:settings.range,teacherName:currentProfile().name});state.meetingBrief.settings={...settings};state.modal=null;document.querySelector('#modal-root').innerHTML='';state.screen='meeting-brief';render();}
function meetingBriefScreen(){const brief=state.meetingBrief;const settings=brief.settings;const s=brief.student;const topics=brief.topics.length?brief.topics.map(topic=>`<span class="brief-topic">${escapeHtml(topic.label)} <b>${topic.count}</b></span>`).join(''):'<span class="brief-muted">No topics recorded.</span>';const notes=items=>settings.includeNotes?items.map(item=>`<li>${escapeHtml(item)}</li>`).join(''):'<li>Teacher-approved notes were not included.</li>';return `<div class="meeting-brief-toolbar"><button class="back" data-nav="log">← Back to Contact Log</button><div><button class="button-secondary" data-action="print-brief">Print</button></div></div><article class="meeting-brief-document"><header class="brief-header"><div><p class="eyebrow">ContactLoop · Meeting Brief</p><h1>${escapeHtml(s?.name||'Student')}</h1><p>Parent communication summary</p></div><div class="brief-meta"><span>Reporting period</span><strong>${escapeHtml(brief.reportingPeriod)}</strong><span>Generated</span><strong>${escapeHtml(brief.generatedDate)}</strong></div></header><section class="brief-section student-information"><h2>Student Information</h2><div class="brief-info-grid"><div><span>Student</span><strong>${escapeHtml(s?.name||'—')}</strong></div><div><span>Teacher</span><strong>${escapeHtml(brief.teacherName)}</strong></div><div><span>Parent / guardian</span><strong>${escapeHtml(`${s?.relation||'Parent'} · ${s?.parent||'—'}`)}</strong></div><div><span>Phone</span><strong>${settings.hidePhone?'Hidden':escapeHtml(s?.phone||'—')}</strong></div></div></section><section class="brief-section"><h2>Communication Overview</h2><div class="overview-grid"><div><strong>${brief.overview.totalAttempts}</strong><span>Contact attempts</span></div><div><strong>${brief.overview.successfulConversations}</strong><span>Successful conversations</span></div><div><strong>${brief.overview.noAnswer}</strong><span>No answers</span></div><div><strong>${brief.overview.busy}</strong><span>Busy</span></div><div><strong>${brief.overview.failed}</strong><span>Failed</span></div><div><strong>${brief.overview.openFollowUps}</strong><span>Open follow-ups</span></div></div><p class="brief-callout">Last successful contact: <b>${escapeHtml(brief.overview.lastSuccessfulContact)}</b></p></section><section class="brief-columns"><section class="brief-section"><h2>Key Topics Discussed</h2><div class="brief-topic-list">${topics}</div></section><section class="brief-section"><h2>Optional Contact Insights</h2><ul>${brief.insights.length?brief.insights.map(item=>`<li>${escapeHtml(item)}</li>`).join(''):'<li>No additional pattern recorded.</li>'}</ul></section></section><section class="brief-columns"><section class="brief-section"><h2>Parent Concerns / Requests</h2><ul>${notes(brief.concerns)}</ul></section><section class="brief-section"><h2>Agreements / Commitments</h2><ul>${notes(brief.agreements)}</ul></section></section><section class="brief-section"><h2>Open Follow-ups</h2>${brief.openFollowUps.length?`<div class="brief-followups">${brief.openFollowUps.map(followUp=>`<div><strong>${escapeHtml(followUp.title||followUp.description||'Follow-up task')}</strong><span>Due ${escapeHtml(formatEventTime(followUp.dueAt||followUp.due_at))} · Open</span></div>`).join('')}</div>`:'<p class="brief-muted">No open follow-ups.</p>'}</section>${settings.includeHistory?`<div class="brief-page-break"></div><section class="brief-section detailed-history"><h2>Detailed Contact History</h2><table><thead><tr><th>Date / Time</th><th>Parent / Guardian</th><th>Method</th><th>Outcome</th><th>Duration</th><th>Topic</th><th>Teacher-approved note</th><th>Follow-up status</th></tr></thead><tbody>${brief.detailedHistory.map(event=>`<tr><td>${escapeHtml(event.displayTime)}</td><td>${escapeHtml(s?.relation||'Parent')}</td><td>${event.kind==='teacher-note'?'Teacher note':'Phone'}</td><td>${escapeHtml(event.kind==='teacher-note'?'—':event.result)}</td><td>${escapeHtml(event.duration||'—')}</td><td>${escapeHtml(event.topic||'—')}</td><td>${escapeHtml(settings.includeNotes?(event.teacherNote||event.note||'—'):'Not included')}</td><td>${escapeHtml(event.followUpStatus)}</td></tr>`).join('')}</tbody></table></section>`:''}</article>`;}
function authScreen(){const isSignUp=state.auth.mode==='sign-up';return `<section class="auth-card"><div class="auth-brand"><span class="brand-mark">C</span><span>Contact<span>Loop</span></span></div><p class="eyebrow">${isSignUp?'Create your workspace':'Welcome back'}</p><h1>${isSignUp?'Start your contact loop.':'Sign in to ContactLoop.'}</h1><p class="auth-copy">${isSignUp?'Create an account to keep your students and guardian contacts private.':'Access your private student and guardian workspace.'}</p>${state.auth.error?`<div class="auth-error">${escapeHtml(state.auth.error)}</div>`:''}${state.auth.message?`<div class="auth-message">${escapeHtml(state.auth.message)}</div>`:''}${state.auth.status==='loading'?'<div class="auth-loading">Checking your session…</div>':`<form class="auth-form" data-auth-form><label>Email<input id="auth-email" type="email" autocomplete="email" value="${escapeHtml(state.auth.email)}" placeholder="teacher@example.com" required></label><label>Password<input id="auth-password" type="password" autocomplete="${isSignUp?'new-password':'current-password'}" value="${escapeHtml(state.auth.password)}" placeholder="At least 6 characters" required></label><button class="button-primary" type="submit">${isSignUp?'Create account':'Sign in'}</button></form><button class="auth-toggle" data-auth-mode>${isSignUp?'Already have an account? Sign in':'New to ContactLoop? Create an account'}</button>`}</section>`;}
function dataStatusScreen(){ const setup=state.error==='setup'; return `<section class="data-status panel"><div class="status-orb">${setup?'↗':'!'}</div><p class="eyebrow">${setup?'Workspace setup':'Could not load your workspace'}</p><h1>${setup?'Connect your workspace':'Your workspace needs attention'}</h1><p>${setup?'Your workspace is not ready yet. Please check the app setup and try again.':escapeHtml(state.error)}</p><button class="button-primary" data-action="retry-data">Try again</button></section>`; }
function screenContent(){ if(state.screen==='home')return homeScreen();if(AUTH_REQUIRED&&state.auth.status!=='authenticated')return authScreen();if(state.loading)return '<section class="data-status panel"><div class="status-orb">↻</div><p class="eyebrow">Loading workspace</p><h1>Getting your contact data.</h1><p>ContactLoop is fetching students, contact history, and follow-ups from Supabase.</p></section>';if(state.error)return dataStatusScreen();if(state.screen==='dashboard')return dashboard();if(state.screen==='students')return studentsScreen();if(state.screen==='import-students')return renderImportScreen(state.importState);if(state.screen==='followups')return followupsScreen();if(state.screen==='log')return logScreen();if(state.screen==='meeting-brief')return meetingBriefScreen();if(state.screen==='detail')return detailScreen(state.selectedStudentId);return dashboard(); }
function render(){const authGate=AUTH_REQUIRED&&state.screen!=='home'&&state.auth.status!=='authenticated';document.querySelector('#app').innerHTML=authGate?`<div class="auth-shell">${screenContent()}</div>`:state.screen==='home'?screenContent():`<div class="app-shell"><aside class="sidebar"><button class="brand" data-home><div class="brand-mark">C</div><div class="brand-copy">Contact<span>Loop</span></div></button><div class="nav-label">Workspace</div><nav class="nav">${renderNav()}</nav><div class="sidebar-foot"><strong>Every contact, automatically tracked.</strong>Let teachers focus on the conversation.${AUTH_REQUIRED?'<button class="sidebar-signout" data-action="sign-out">Sign out</button>':''}</div></aside><main class="main">${actionErrorBanner()}${screenContent()}</main></div>`; bindEvents(); }

function openCallFlow(id){state.selectedStudentId=id;state.modal={step:'planned-topic',plannedTopic:null,result:null,discussedTopics:[],followUp:'Tomorrow',note:''};renderModal();}
function renderPlannedTopicModal(){const m=state.modal;document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal planned-topic-modal"><div class="modal-header"><div><p class="eyebrow">Before you call</p><h2>What’s this call about?</h2><p>Choose a reason so ContactLoop can keep the outreach context clear.</p></div><button class="close" data-close>×</button></div><div class="topic-grid">${CALL_TOPICS.map(topic=>`<button class="topic ${m.plannedTopic===topic?'selected':''}" data-planned-topic="${topic}">${topic}</button>`).join('')}</div><div class="modal-footer"><button class="button-cancel" data-close>Cancel</button><button class="button-primary" data-call-now>Call now</button></div></div></div>`;document.querySelectorAll('[data-planned-topic]').forEach(button=>button.onclick=()=>{state.modal.plannedTopic=button.dataset.plannedTopic;renderModal()});document.querySelector('[data-call-now]')?.addEventListener('click',()=>{const plannedTopic=state.modal.plannedTopic;if(TELEPHONY_PROVIDER==='twilio'){state.modal=null;document.querySelector('#modal-root').innerHTML='';startRealCall(state.selectedStudentId,plannedTopic||null);}else{state.modal={step:'outcome',result:null,plannedTopic:plannedTopic||null,discussedTopics:plannedTopic?[plannedTopic]:[],followUp:'Tomorrow',note:''};renderModal()}});}
function renderModal(){const m=state.modal;if(m.step==='planned-topic'){renderPlannedTopicModal();return;}if(m.step==='voice'){document.querySelector('#modal-root').innerHTML=renderVoiceModal();bindVoiceModalEvents();return;}if(m.step==='teacher-note'){document.querySelector('#modal-root').innerHTML=renderTeacherNoteModal();bindTeacherNoteModalEvents();return;}if(m.step==='reschedule'){renderRescheduleModal();return;}if(m.step==='confirm'){renderConfirmModal();return;}if(m.step==='guardian-form'){renderGuardianFormModal();return;}if(m.step==='pick'){const query=(m.search||'').trim().toLowerCase();const matches=state.students.filter(s=>`${s.name} ${s.parent} ${s.phone}`.toLowerCase().includes(query));document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-header"><div><h2>Who are you calling?</h2><p>Choose a student to start a parent contact.</p></div><button class="close" data-close>×</button></div><div class="picker-search"><span>⌕</span><input id="student-search" value="${escapeHtml(m.search||'')}" placeholder="Search students or parents…"></div><div class="picker-list">${matches.map(s=>`<button class="picker-row" data-pick-student="${escapeHtml(s.id)}">${avatar(s)}<span><strong>${escapeHtml(s.name)}</strong><small>${escapeHtml(s.relation)} · ${escapeHtml(s.parent)}</small></span><b>→</b></button>`).join('')||'<div class="empty-state">No students match that search.</div>'}</div><div class="modal-footer"><button class="button-cancel" data-close>Cancel</button></div></div></div>`;bindModalEvents();return;}const s=student(state.selectedStudentId);let body='';if(m.step==='outcome')body=`<div class="modal-label">What happened?</div><div class="outcome-grid">${[['Connected','7m 43s · conversation complete'],['No Answer','Rings out'],['Busy','Line was busy'],['Failed','Could not connect']].map(([r,d])=>`<button class="outcome ${m.result===r?'selected':''}" data-outcome="${r}">${r}<span>${d}</span></button>`).join('')}</div>`;if(m.step==='details')body=`<p class="planned-topic-note">Planned topic: <strong>${m.plannedTopic||"Not specified"}</strong></p><div class="modal-label">What did you discuss?</div><div class="topic-grid">${CALL_TOPICS.map(t=>`<button class="topic ${m.discussedTopics?.includes(t)?'selected':''}" data-topic="${t}">${t}</button>`).join('')}</div><label class="modal-label" for="note">Optional note <span style="text-transform:none;letter-spacing:0">· teacher confirmed</span></label><textarea id="note" placeholder="e.g. Dad confirmed Friday at 2 and asked about transportation.">${escapeHtml(m.note)}</textarea>`;if(m.step==='followup')body=`<div class="modal-label">When should we try again?</div><div class="followup-options">${['Tomorrow','In 2 days','In 3 days','Next week'].map(t=>`<button class="followup-option ${m.followUp===t?'selected':''}" data-followup="${t}">${t}</button>`).join('')}</div>`;document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-header"><div><h2>${m.step==='outcome'?'Start a contact':m.step==='details'?'Nice conversation.':'Keep the loop closed.'}</h2><p>${m.step==='outcome'?`Calling ${escapeHtml(s.parent)}, ${escapeHtml(s.relation.toLowerCase())} of ${escapeHtml(s.name)}`:m.step==='details'?'One tap to keep the record useful.':'We’ll bring this back to your attention when it’s due.'}</p></div><button class="close" data-close>×</button></div><div class="call-preview">${avatar(s)}<div><strong>${escapeHtml(s.name)}</strong><span>${escapeHtml(s.relation)} · ${escapeHtml(s.phone)}</span></div></div>${body}<div class="modal-footer"><button class="button-cancel" data-close>Cancel</button><button class="button-primary" ${m.step==='outcome'&&!m.result?'disabled':''} data-modal-next>${m.step==='outcome'?(m.result==='Connected'?'Continue':'Schedule follow-up'):m.step==='details'?'Save note':'Save contact'}</button></div></div></div>`;bindModalEvents();}
function followUpDueAt(label){ const days=label==='Tomorrow'?1:label==='In 2 days'?2:label==='In 3 days'?3:7; const due=new Date(); due.setDate(due.getDate()+days); due.setHours(9,0,0,0); return due.toISOString(); }
async function completeCall(){const s=student(state.selectedStudentId),m=state.modal;try{await createContactEvent({studentId:s.id,guardianId:s.guardianId,result:m.result,durationSeconds:m.result==='Connected'?463:null,plannedTopic:m.plannedTopic,discussedTopics:normalizeDiscussedTopics(m.result,m.plannedTopic,m.discussedTopics),topic:m.result==='Connected'?topicLabel(m.plannedTopic,m.discussedTopics,m.result):m.plannedTopic,teacherNote:m.note,followUpDueAt:m.result==='Connected'?null:followUpDueAt(m.followUp)});state.modal=null;document.querySelector('#modal-root').innerHTML='';state.screen='detail';await refreshData();}catch(error){state.modal=null;document.querySelector('#modal-root').innerHTML='';setActionError(error,'Unable to save this contact event.');}}
function bindVoiceModalEvents(){document.querySelectorAll('[data-voice-cancel]').forEach(button=>button.onclick=closeVoiceNote);document.querySelector('[data-voice-start]')?.addEventListener('click',startVoiceRecording);document.querySelector('[data-voice-stop]')?.addEventListener('click',stopVoiceRecording);document.querySelector('[data-voice-retry]')?.addEventListener('click',()=>{state.voiceNote=createVoiceNoteState();renderModal()});document.querySelector('[data-voice-save]')?.addEventListener('click',saveVoiceNote);document.querySelector('#voice-transcript')?.addEventListener('input',event=>{state.voiceNote.transcript=event.target.value;});}
function bindModalEvents(){document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{state.modal=null;document.querySelector('#modal-root').innerHTML=''});document.querySelectorAll('[data-pick-student]').forEach(b=>b.onclick=()=>openCallFlow(b.dataset.pickStudent));document.querySelectorAll('[data-outcome]').forEach(b=>b.onclick=()=>{state.modal.result=b.dataset.outcome;renderModal()});document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{const topic=b.dataset.topic;const topics=state.modal.discussedTopics||[];state.modal.discussedTopics=topics.includes(topic)?topics.filter(item=>item!==topic):[...topics,topic];renderModal()});document.querySelectorAll('[data-followup]').forEach(b=>b.onclick=()=>{state.modal.followUp=b.dataset.followup;renderModal()});const search=document.querySelector('#student-search');if(search)search.oninput=()=>{state.modal.search=search.value;renderModal();document.querySelector('#student-search')?.focus();};const note=document.querySelector('#note');if(note)note.oninput=()=>state.modal.note=note.value;const next=document.querySelector('[data-modal-next]');if(next)next.onclick=()=>{if(state.modal.step==='outcome'){state.modal.step=state.modal.result==='Connected'?'details':'followup';renderModal()}else completeCall()};}
function openParentPicker(){state.modal={step:'pick',search:''};renderModal();}
function updateGuardianField(event){const [index,field]=event.currentTarget.dataset.guardianField.split(':');const guardians=state.modal.guardians||[];guardians[Number(index)]={...guardians[Number(index)],[field]:event.currentTarget.value};state.modal.guardians=guardians;state.modal.guardianName=guardians[0]?.name||'';state.modal.relation=guardians[0]?.relation||'Mom';state.modal.phone=guardians[0]?.phone||'';updateAddStudentSaveState();}
function updateAddStudentSaveState(){const first=state.modal?.guardians?.[0];const save=document.querySelector('[data-save-student]');if(save)save.disabled=!state.modal?.name?.trim()||!first?.name?.trim()||!first?.phone?.trim();}
function renderAddStudentModalV2(){const m=state.modal;const guardians=m.guardians||[{name:m.guardianName||'',relation:m.relation||'Mom',phone:m.phone||''}];const first=guardians[0];const extraGuardians=guardians.slice(1).map((guardian,offset)=>{const index=offset+1;return `<div class="guardian-entry"><div class="guardian-entry-head"><strong>Guardian ${index+1}</strong><button type="button" class="remove-guardian" data-remove-guardian="${index}">Remove</button></div><label>Parent / guardian name<input data-guardian-field="${index}:name" value="${escapeHtml(guardian.name)}" placeholder="e.g. David Lee"></label><label>Relationship<select data-guardian-field="${index}:relation"><option ${guardian.relation==='Mom'?'selected':''}>Mom</option><option ${guardian.relation==='Dad'?'selected':''}>Dad</option><option ${guardian.relation==='Guardian'?'selected':''}>Guardian</option><option ${guardian.relation==='Other'?'selected':''}>Other</option></select></label><label>Phone number<input data-guardian-field="${index}:phone" value="${escapeHtml(guardian.phone)}" placeholder="(415) 555-0199"></label></div>`}).join('');document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal add-student-modal"><div class="modal-header"><div><h2>Add a student</h2></div><button class="close" data-close>×</button></div><div class="form-grid add-student-grid"><label>Student name<input id="student-name" value="${escapeHtml(m.name)}" placeholder="e.g. Jordan Lee"></label><label>Parent / guardian name<input data-guardian-field="0:name" value="${escapeHtml(first.name)}" placeholder="e.g. Taylor Lee"></label><label>Relationship<select data-guardian-field="0:relation"><option ${first.relation==='Mom'?'selected':''}>Mom</option><option ${first.relation==='Dad'?'selected':''}>Dad</option><option ${first.relation==='Guardian'?'selected':''}>Guardian</option><option ${first.relation==='Other'?'selected':''}>Other</option></select></label><label>Phone number<input data-guardian-field="0:phone" value="${escapeHtml(first.phone)}" placeholder="(415) 555-0199"></label></div><div class="guardian-list">${extraGuardians}</div><button type="button" class="add-guardian-button" data-add-guardian>+ Add another guardian</button><div class="modal-footer"><button class="button-cancel" data-close>Cancel</button><button class="button-primary" data-save-student ${!m.name.trim()||!first.name.trim()||!first.phone.trim()?'disabled':''}>Add student</button></div></div></div>`;bindAddStudentModalEvents();}
function bindAddStudentModalEvents(){document.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>{state.modal=null;document.querySelector('#modal-root').innerHTML=''});document.querySelector('#student-name')?.addEventListener('input',event=>{state.modal.name=event.target.value;updateAddStudentSaveState()});document.querySelectorAll('[data-guardian-field]').forEach(field=>{field.addEventListener('input',updateGuardianField);field.addEventListener('change',updateGuardianField)});document.querySelector('[data-add-guardian]')?.addEventListener('click',()=>{state.modal.guardians=[...(state.modal.guardians||[]),{name:'',relation:'Mom',phone:''}];renderAddStudentModalV2()});document.querySelectorAll('[data-remove-guardian]').forEach(button=>button.addEventListener('click',()=>{state.modal.guardians=state.modal.guardians.filter((_,index)=>index!==Number(button.dataset.removeGuardian));renderAddStudentModalV2()}));document.querySelector('[data-save-student]')?.addEventListener('click',saveNewStudent);}
function openAddStudent(){state.modal={step:'add-student',name:'',guardianName:'',relation:'Mom',phone:'',guardians:[{name:'',relation:'Mom',phone:''}]};renderAddStudentModalV2();}
async function saveNewStudent(){const m=state.modal;const guardians=(m.guardians||[]).filter(guardian=>guardian.name.trim()||guardian.phone.trim());if(!m.name.trim()||!guardians[0]?.name.trim()||!guardians[0]?.phone.trim())return;try{await createStudent({name:m.name.trim(),guardians});state.modal=null;document.querySelector('#modal-root').innerHTML='';state.screen='students';await refreshData();}catch(error){state.modal=null;document.querySelector('#modal-root').innerHTML='';setActionError(error,'Unable to add this student.');}}
async function markFollowUpDone(id){try{await updateFollowUp(id,{status:'completed'});await refreshData();}catch(error){setActionError(error,'Unable to complete this follow-up.');}}
async function dismissFollowUp(id){try{await updateFollowUp(id,{status:'dismissed'});await refreshData();}catch(error){setActionError(error,'Unable to dismiss this follow-up.');}}
function openDeleteFollowUp(id){const followUp=state.followUps.find(item=>item.id===id);const s=followUp&&student(followUp.studentId||followUp.student_id);openConfirmDialog({title:'Delete follow-up?',body:`Remove the scheduled follow-up for ${s?.name||'this student'}? This can’t be undone.`,confirmLabel:'Delete follow-up',action:async()=>{await requireFacadeAction('deleteFollowUp')(id);await refreshData();}});}
function openDeleteContactEvent(eventId){const e=state.events.find(event=>event.id===eventId);const s=e&&eventStudent(e);openConfirmDialog({title:'Delete contact record?',body:`Delete the ${e?.result||'contact'} record for ${s?.name||'this student'}? The outcome, topics, and teacher-approved note will be removed. This can’t be undone.`,confirmLabel:'Delete record',action:async()=>{await requireFacadeAction('deleteContactEvent')(eventId);await refreshData();}});}
function openRescheduleModal(id){const followUp=state.followUps.find(item=>item.id===id);const dueAt=followUp?.dueAt||followUp?.due_at;const dueDate=dueAt?new Date(dueAt):new Date();const value=Number.isNaN(dueDate.getTime())?'':`${dueDate.getFullYear()}-${String(dueDate.getMonth()+1).padStart(2,'0')}-${String(dueDate.getDate()).padStart(2,'0')}`;state.modal={step:'reschedule',followUpId:id,value,error:null,saving:false};renderModal();}
function renderRescheduleModal(){const m=state.modal;const followUp=state.followUps.find(item=>item.id===m.followUpId);const s=student(followUp?.studentId||followUp?.student_id);document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal reschedule-modal"><div class="modal-header"><div><p class="eyebrow">Keep the loop closed</p><h2>Reschedule follow-up</h2><p>${escapeHtml(s?.name||'This student')} · Choose the next contact date.</p></div><button class="close" data-reschedule-cancel>×</button></div>${m.error?`<div class="ai-summary-error">${escapeHtml(m.error)}</div>`:''}<label class="modal-label" for="reschedule-date">Next follow-up date</label><input id="reschedule-date" type="date" value="${escapeHtml(m.value||'')}" min="${new Date().toISOString().slice(0,10)}"><div class="modal-footer"><button class="button-cancel" data-reschedule-cancel>Cancel</button><button class="button-primary" data-reschedule-save ${m.saving||!m.value?'disabled':''}>Reschedule</button></div></div></div>`;bindRescheduleModalEvents();}
function bindRescheduleModalEvents(){document.querySelectorAll('[data-reschedule-cancel]').forEach(button=>button.onclick=()=>{state.modal=null;document.querySelector('#modal-root').innerHTML='';});const input=document.querySelector('#reschedule-date');if(input)input.onchange=()=>{state.modal.value=input.value;const save=document.querySelector('[data-reschedule-save]');if(save)save.disabled=!input.value||state.modal.saving;};document.querySelector('[data-reschedule-save]')?.addEventListener('click',saveRescheduledFollowUp);input?.focus();}
async function saveRescheduledFollowUp(){const m=state.modal;const dueAt=parseFollowUpDate(m?.value);if(!dueAt){state.modal={...m,error:'Choose a valid date.',saving:false};return renderModal();}state.modal={...m,saving:true,error:null};renderModal();try{await updateFollowUp(m.followUpId,{due_at:dueAt,status:'open'});state.modal=null;document.querySelector('#modal-root').innerHTML='';await refreshData();}catch(error){state.modal={...m,saving:false,error:error.message||'Unable to reschedule this follow-up.'};renderModal();}}
function openImportStudents(){state.screen='import-students';state.importState={step:'upload',fileName:'',headers:[],rawRows:[],mapping:{},rows:[],stats:null,result:null,error:null};render();}
async function handleImportFile(file){if(!file)return;const extension=file.name.toLowerCase().split('.').pop();if(!['csv','xlsx'].includes(extension)){state.importState={...state.importState,error:'Please choose a CSV or XLSX file.'};render();return;}try{const parsed=extension==='csv'?parseCsvText(await file.text()):parseWorkbook(await file.arrayBuffer());if(!parsed.headers.length)throw new Error('This file does not contain a header row.');state.importState={...state.importState,fileName:file.name,headers:parsed.headers,rawRows:parsed.rows,mapping:suggestColumnMapping(parsed.headers),error:null,step:'mapping'};render();}catch(error){state.importState={...state.importState,error:error.message||'Unable to parse this file.'};render();}}
function continueImportMapping(){const mapping=state.importState.mapping;if(!Object.values(mapping).some(value=>value==='student_full_name'||value==='student_first_name')||!Object.values(mapping).includes('guardian_name')){state.importState={...state.importState,error:'Map a student name and guardian name before continuing.'};render();return;}const rows=normalizeImportRows(state.importState.rawRows,mapping);const validation=validateImportRows(rows,state.students);state.importState={...state.importState,...validation,step:'review',error:null};render();}
function editImportRow(index,field,value){const rows=state.importState.rows.map((row,rowIndex)=>{if(rowIndex!==index)return row;const next={...row,student:{...row.student},guardian:{...row.guardian}};if(field==='student'){next.student.name=value;const parts=value.trim().split(/\s+/);next.student.firstName=parts.slice(0,-1).join(' ');next.student.lastName=parts.at(-1)||'';next.studentKey=value.trim().toLowerCase().replace(/\s+/g,' ');}else next.guardian[field]=value;return next;});const validation=validateImportRows(rows,state.students);state.importState={...state.importState,...validation};render();}
async function submitImport(){const chosen=state.importState.rows.filter(row=>row.status==='ready'||(row.status==='duplicate'&&row.action!=='skip'));if(!chosen.length)return;state.importState={...state.importState,error:null,loading:true};render();try{const result=await importStudents(buildImportPayload(chosen));state.importState={...state.importState,result,loading:false,step:'complete',rows:[],rawRows:[]};state.screen='import-students';await refreshData();}catch(error){state.importState={...state.importState,loading:false,error:error.message||'Unable to import students.'};render();}}
function openAuth(mode){state.auth={...state.auth,mode,error:null,message:null};state.screen=state.auth.status==='authenticated'?'dashboard':'auth';render();}
async function handleAuthSubmit(event){event.preventDefault();const email=document.querySelector('#auth-email')?.value.trim()||'';const password=document.querySelector('#auth-password')?.value||'';state.auth={...state.auth,email,password,status:'loading',error:null,message:null};render();try{const result=state.auth.mode==='sign-up'?await signUpWithPassword(email,password):await signInWithPassword(email,password);if(result.error)throw result.error;if(state.auth.mode==='sign-up'&&!result.data?.session){state.auth={...state.auth,status:'signed-out',password:'',message:'Check your email to confirm your account.'};render();return;}state.auth={...state.auth,status:'authenticated',session:result.data?.session??state.auth.session,password:'',error:null,message:null};state.loading=true;render();await refreshData();}catch(error){state.auth={...state.auth,status:'signed-out',password:'',error:error.message||'Unable to authenticate.',message:null};render();}}
async function initializeAuth(){try{const session=await getAuthSession();state.auth={...state.auth,status:session?'authenticated':'signed-out',session,error:null};render();if(session)await refreshData();}catch(error){state.auth={...state.auth,status:'signed-out',error:error.message||'Unable to check your session.'};render();}subscribeToAuthChanges((_event,session)=>{state.auth={...state.auth,status:session?'authenticated':'signed-out',session,error:null};if(session){state.loading=true;refreshData();}else{state.students=[];state.events=[];state.followUps=[];state.teacherNotes=[];state.loading=false;}render();});}
function bindEvents(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{state.screen=b.dataset.nav;render()});document.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>{state.screen='home';render()});document.querySelectorAll('[data-student]').forEach(b=>b.onclick=()=>{state.screen='detail';state.selectedStudentId=b.dataset.student;render()});document.querySelectorAll('[data-call]').forEach(b=>b.onclick=()=>handleCallClick(b.dataset.call));document.querySelectorAll('[data-add-teacher-note]').forEach(b=>b.onclick=()=>openTeacherNote(b.dataset.addTeacherNote));document.querySelectorAll('[data-add-teacher-voice]').forEach(b=>b.onclick=()=>openVoiceNote(b.dataset.addTeacherVoice));document.querySelectorAll('[data-ai-generate]').forEach(b=>b.onclick=()=>generateAiContactSummary(b.dataset.aiGenerate));document.querySelectorAll('[data-ai-edit]').forEach(b=>b.onclick=()=>beginAiSummaryEdit(b.dataset.aiEdit));document.querySelectorAll('[data-ai-cancel]').forEach(b=>b.onclick=()=>cancelAiSummaryEdit(b.dataset.aiCancel));document.querySelectorAll('[data-ai-save]').forEach(b=>b.onclick=()=>saveAiSummaryEdits(b.dataset.aiSave));document.querySelectorAll('[data-ai-approve]').forEach(b=>b.onclick=()=>approveAiSummary(b.dataset.aiApprove));document.querySelectorAll('[data-ai-remove]').forEach(b=>b.onclick=()=>removeAiSummary(b.dataset.aiRemove));document.querySelectorAll('[data-ai-regenerate]').forEach(b=>b.onclick=()=>generateAiContactSummary(b.dataset.aiRegenerate));document.querySelectorAll('[data-ai-menu-toggle]').forEach(b=>b.onclick=event=>{event.stopPropagation();document.querySelector(`[data-ai-menu="${b.dataset.aiMenuToggle}"]`)?.classList.toggle('open')});document.querySelectorAll('[data-ai-item]').forEach(input=>input.oninput=()=>{const result=state.aiContactBriefs[state.selectedStudentId];if(result?.editor)result.editor=updateBriefItem(result.editor,input.dataset.aiItem,Number(input.dataset.aiIndex),input.value)});document.querySelectorAll('[data-ai-delete]').forEach(b=>b.onclick=()=>{const [field,index]=b.dataset.aiDelete.split(':');const result=state.aiContactBriefs[state.selectedStudentId];if(result?.editor){result.editor=deleteBriefItem(result.editor,field,Number(index));render()}});document.querySelector('[data-ai-next-step]')?.addEventListener('input',event=>{const result=state.aiContactBriefs[state.selectedStudentId];if(result?.editor)result.editor.brief.suggested_next_step=event.target.value});document.querySelectorAll('[data-log-event]').forEach(row=>{row.onclick=()=>openLogDetail(row.dataset.logEvent);row.onkeydown=event=>{if(event.key==='Enter'||event.key===' ')openLogDetail(row.dataset.logEvent)}});document.querySelectorAll('[data-action="demo"]').forEach(b=>b.onclick=()=>{state.screen='dashboard';render()});document.querySelectorAll('[data-action="sign-in"]').forEach(b=>b.onclick=()=>openAuth('sign-in'));document.querySelectorAll('[data-action="sign-up"]').forEach(b=>b.onclick=()=>openAuth('sign-up'));document.querySelector('[data-action="try-emma"]')?.addEventListener('click',()=>{const emma=state.students.find(s=>s.name==='Emma Johnson');if(!emma)return;state.screen='detail';state.selectedStudentId=emma.id;render();handleCallClick(emma.id)});document.querySelector('[data-action="call-parent"]')?.addEventListener('click',openParentPicker);document.querySelector('[data-action="retry-data"]')?.addEventListener('click',refreshData);document.querySelector('[data-action="new-student"]')?.addEventListener('click',openAddStudent);
  document.querySelectorAll('[data-followup-menu-toggle]').forEach(button=>button.onclick=event=>{event.stopPropagation();const menu=document.querySelector(`[data-followup-menu="${button.dataset.followupMenuToggle}"]`);document.querySelectorAll('.followup-menu.open').forEach(openMenu=>{if(openMenu!==menu)openMenu.classList.remove('open')});menu?.classList.toggle('open')});
  document.querySelectorAll('[data-followup-done]').forEach(button=>button.onclick=()=>markFollowUpDone(button.dataset.followupDone));
  document.querySelectorAll('[data-followup-reschedule]').forEach(button=>button.onclick=()=>openRescheduleModal(button.dataset.followupReschedule));
  document.querySelectorAll('[data-followup-dismiss]').forEach(button=>button.onclick=()=>dismissFollowUp(button.dataset.followupDismiss));
  document.querySelectorAll('[data-followup-delete]').forEach(button=>button.onclick=()=>openDeleteFollowUp(button.dataset.followupDelete));
  document.querySelectorAll('[data-followup-history]').forEach(button=>button.onclick=()=>{state.screen='detail';state.selectedStudentId=button.dataset.followupHistory;render()});
  document.querySelectorAll('[data-event-delete]').forEach(button=>button.onclick=()=>openDeleteContactEvent(button.dataset.eventDelete));
  document.querySelectorAll('[data-add-guardian]').forEach(button=>button.onclick=()=>openAddGuardian(button.dataset.addGuardian));
  document.querySelectorAll('[data-edit-guardian]').forEach(button=>button.onclick=()=>openEditGuardian(button.dataset.editGuardian));
  document.querySelectorAll('[data-remove-guardian]').forEach(button=>button.onclick=()=>openDeleteGuardian(button.dataset.removeGuardian));
  document.querySelectorAll('[data-edit-teacher-note]').forEach(button=>button.onclick=()=>openEditTeacherNote(button.dataset.editTeacherNote));
  document.querySelectorAll('[data-delete-teacher-note]').forEach(button=>button.onclick=()=>openDeleteTeacherNote(button.dataset.deleteTeacherNote));
  document.querySelectorAll('[data-dismiss-action-error]').forEach(button=>button.onclick=()=>{state.actionError=null;render()});
  const rangeSelect=document.querySelector('#dashboard-range');if(rangeSelect)rangeSelect.onchange=()=>{state.dashboardRange={...state.dashboardRange,preset:rangeSelect.value};if(rangeSelect.value!=='custom')state.dashboardRange={preset:rangeSelect.value,from:'',to:''};render()};
  const fromInput=document.querySelector('#dashboard-from');if(fromInput)fromInput.onchange=()=>{state.dashboardRange={...state.dashboardRange,from:fromInput.value};render()};
  const toInput=document.querySelector('#dashboard-to');if(toInput)toInput.onchange=()=>{state.dashboardRange={...state.dashboardRange,to:toInput.value};render()};
  const studentSearchInput=document.querySelector('#student-page-search');if(studentSearchInput)studentSearchInput.oninput=()=>{const value=studentSearchInput.value;const cursor=studentSearchInput.selectionStart??value.length;state.studentSearch=value;render();const next=document.querySelector('#student-page-search');if(next){next.focus();next.setSelectionRange(cursor,cursor)}};
  const logSearch=document.querySelector('#log-search');if(logSearch)logSearch.oninput=()=>{const value=logSearch.value;const cursor=logSearch.selectionStart??value.length;state.logFilters={...state.logFilters,search:value};render();const next=document.querySelector('#log-search');if(next){next.focus();next.setSelectionRange(cursor,cursor)}};
  const logRange=document.querySelector('#log-range');if(logRange)logRange.onchange=()=>{state.logFilters={...state.logFilters,range:{preset:logRange.value,from:'',to:''}};render()};
  const logOutcome=document.querySelector('#log-outcome');if(logOutcome)logOutcome.onchange=()=>{state.logFilters={...state.logFilters,outcome:logOutcome.value};render()};
  const logStudent=document.querySelector('#log-student');if(logStudent)logStudent.onchange=()=>{state.logFilters={...state.logFilters,studentId:logStudent.value};render()};
  const logFrom=document.querySelector('#log-from');if(logFrom)logFrom.onchange=()=>{state.logFilters={...state.logFilters,range:{...state.logFilters.range,from:logFrom.value}};render()};
  const logTo=document.querySelector('#log-to');if(logTo)logTo.onchange=()=>{state.logFilters={...state.logFilters,range:{...state.logFilters.range,to:logTo.value}};render()};
  document.querySelector('[data-action="export-log"]')?.addEventListener('click',exportFilteredContactLog);
  document.querySelector('[data-action="meeting-brief"]')?.addEventListener('click',openMeetingBriefSettings);
  document.querySelector('[data-action="print-brief"]')?.addEventListener('click',()=>window.print());
  document.querySelector('[data-action="sign-out"]')?.addEventListener('click',handleSignOut);
}
async function handleSignOut(){try{await signOut();}finally{state.auth={...state.auth,status:'signed-out',session:null,email:'',password:'',error:null,message:null};state.students=[];state.events=[];state.followUps=[];state.teacherNotes=[];state.loading=false;state.screen='home';state.modal=null;document.querySelector('#modal-root').innerHTML='';render();}}
document.addEventListener('click',event=>{
  const button=event.target.closest?.('[data-ai-add]');
  if(!button)return;
  event.preventDefault();
  event.stopPropagation();
  openAiItemDialog(button.dataset.aiAdd);
},true);
const modalObserver=new MutationObserver(()=>{const skip=document.querySelector('.modal:has(#note) .modal-footer .button-cancel');if(skip&&!skip.dataset.noteSkip){skip.dataset.noteSkip='true';skip.removeAttribute('data-close');skip.onclick=()=>completeCall();}const search=document.querySelector('#student-search');if(search&&!search.dataset.nativeSearch){search.dataset.nativeSearch='true';search.oninput=()=>{const query=search.value.trim().toLowerCase();state.modal.search=search.value;document.querySelectorAll('.picker-row').forEach(row=>{row.hidden=!row.textContent.toLowerCase().includes(query);});};}});modalObserver.observe(document.querySelector('#modal-root'),{childList:true,subtree:true});
render();
document.addEventListener('submit',event=>{if(event.target.matches('[data-auth-form]'))handleAuthSubmit(event);});
document.addEventListener('click',event=>{if(event.target.closest?.('[data-auth-mode]')){state.auth={...state.auth,mode:state.auth.mode==='sign-up'?'sign-in':'sign-up',error:null,message:null};render();}});
document.addEventListener('click',event=>{const button=event.target.closest?.('[data-ai-voice]');if(button)openVoiceNote(button.dataset.aiVoice);});
document.addEventListener('click',event=>{
  const importButton=event.target.closest?.('[data-action="import-students"]');
  if(importButton){openImportStudents();return;}
  const back=event.target.closest?.('[data-import-back]');
  if(back){
    if(state.importState?.step==='mapping')state.importState={...state.importState,step:'upload',error:null};
    else if(state.importState?.step==='review')state.importState={...state.importState,step:'mapping',error:null};
    else {state.screen='students';state.importState=null;}
    render();
    return;
  }
  if(event.target.closest?.('[data-import-continue]')){continueImportMapping();return;}
  if(event.target.closest?.('[data-import-submit]')){submitImport();return;}
  if(event.target.closest?.('[data-download-template]')){downloadContactLoopTemplate();return;}
  if(event.target.closest?.('[data-view-students]')){state.screen='students';state.importState=null;render();}
});
document.addEventListener('change',event=>{
  if(event.target.matches?.('#import-file')){handleImportFile(event.target.files?.[0]);return;}
  if(event.target.matches?.('[data-import-mapping]')){state.importState={...state.importState,mapping:{...state.importState.mapping,[event.target.dataset.importMapping]:event.target.value},error:null};render();return;}
  if(event.target.matches?.('[data-import-action]')){const index=Number(event.target.dataset.importAction);const rows=state.importState.rows.map((row,rowIndex)=>rowIndex===index?{...row,action:event.target.value}:row);state.importState={...state.importState,rows,stats:{...state.importState.stats}};render();return;}
  if(event.target.matches?.('[data-import-edit]')){const [index,field]=event.target.dataset.importEdit.split(':');editImportRow(Number(index),field,event.target.value);}
});
document.addEventListener('dragover',event=>{if(event.target.closest?.('.import-dropzone'))event.preventDefault();});
document.addEventListener('drop',event=>{const zone=event.target.closest?.('.import-dropzone');if(!zone)return;event.preventDefault();handleImportFile(event.dataTransfer?.files?.[0]);});
function openDeleteStudent(studentId){if(!student(studentId))return;state.studentMenuId=null;state.modal={step:'delete-student',studentId,error:null};renderDeleteStudentModal();}
function openEditStudent(studentId){const s=student(studentId);if(!s)return;state.studentMenuId=null;state.modal={step:'edit-student',studentId,name:s.name,guardianName:s.parent,relation:s.relation,phone:s.phone,error:null,saving:false};renderEditStudentModal();}
function renderEditStudentModal(){const m=state.modal;const s=student(m.studentId);if(!s){state.modal=null;document.querySelector('#modal-root').innerHTML='';return;}document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal edit-student-modal" role="dialog" aria-modal="true" aria-labelledby="edit-student-title"><div class="modal-header"><div><p class="eyebrow">Caseload</p><h2 id="edit-student-title">Edit student</h2><p>Update this student and primary guardian.</p></div><button class="close" data-edit-student-close aria-label="Close">×</button></div>${m.error?`<div class="modal-error">${escapeHtml(m.error)}</div>`:''}<div class="form-grid"><label>Student name<input id="edit-student-name" value="${escapeHtml(m.name)}" autocomplete="name"></label><label>Parent / guardian name<input id="edit-guardian-name" value="${escapeHtml(m.guardianName)}" autocomplete="name"></label><label>Relationship<select id="edit-guardian-relation"><option ${m.relation==='Mom'?'selected':''}>Mom</option><option ${m.relation==='Dad'?'selected':''}>Dad</option><option ${m.relation==='Guardian'?'selected':''}>Guardian</option><option ${m.relation==='Other'?'selected':''}>Other</option></select></label><label>Phone number<input id="edit-guardian-phone" value="${escapeHtml(m.phone)}" autocomplete="tel"></label></div><div class="modal-footer"><button class="button-cancel" data-edit-student-close ${m.saving?'disabled':''}>Cancel</button><button class="button-primary" data-save-edited-student ${m.saving||!m.name.trim()||!m.guardianName.trim()||!m.phone.trim()?'disabled':''}>${m.saving?'Saving…':'Save changes'}</button></div></div></div>`;document.querySelectorAll('[data-edit-student-close]').forEach(button=>button.onclick=()=>{state.modal=null;document.querySelector('#modal-root').innerHTML='';});document.querySelector('#edit-student-name')?.addEventListener('input',event=>{state.modal.name=event.target.value;updateEditStudentSaveState();});document.querySelector('#edit-guardian-name')?.addEventListener('input',event=>{state.modal.guardianName=event.target.value;updateEditStudentSaveState();});document.querySelector('#edit-guardian-relation')?.addEventListener('change',event=>{state.modal.relation=event.target.value;});document.querySelector('#edit-guardian-phone')?.addEventListener('input',event=>{state.modal.phone=event.target.value;updateEditStudentSaveState();});document.querySelector('[data-save-edited-student]')?.addEventListener('click',saveEditedStudent);}
function updateEditStudentSaveState(){const button=document.querySelector('[data-save-edited-student]');if(button)button.disabled=state.modal.saving||!state.modal.name.trim()||!state.modal.guardianName.trim()||!state.modal.phone.trim();}
async function saveEditedStudent(){const m=state.modal;const s=student(m.studentId);if(!s||m.saving||!m.name.trim()||!m.guardianName.trim()||!m.phone.trim())return;state.modal={...m,saving:true,error:null};renderEditStudentModal();try{await updateStudent({studentId:s.id,guardianId:s.guardianId,name:m.name.trim(),guardianName:m.guardianName.trim(),relation:m.relation,phone:m.phone.trim()});await refreshData();state.modal=null;document.querySelector('#modal-root').innerHTML='';state.screen='students';render();}catch(error){state.modal={...m,saving:false,error:error.message||'Unable to save student changes.'};renderEditStudentModal();}}
function renderDeleteStudentModal(){const m=state.modal;const s=student(m.studentId);if(!s){state.modal=null;document.querySelector('#modal-root').innerHTML='';return;}document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal delete-student-modal" role="dialog" aria-modal="true" aria-labelledby="delete-student-title"><div class="modal-header"><div><p class="eyebrow">Caseload</p><h2 id="delete-student-title">Delete student?</h2><p>This removes this student and all associated records.</p></div><button class="close" data-delete-student-close aria-label="Close">×</button></div><div class="delete-student-summary">${avatar(s)}<div><strong>${escapeHtml(s.name)}</strong><span>${escapeHtml(s.relation)} · ${escapeHtml(s.parent)}</span></div></div>${m.error?`<div class="modal-error">${escapeHtml(m.error)}</div>`:''}<p class="modal-copy">Contact history, follow-ups, teacher notes, and AI summaries for this student will be deleted. This action can’t be undone.</p><div class="modal-footer"><button class="button-cancel" data-delete-student-close ${state.busy==='delete-student'?'disabled':''}>Cancel</button><button class="button-danger" data-delete-student-confirm ${state.busy==='delete-student'?'disabled':''}>${state.busy==='delete-student'?'Deleting…':'Delete student'}</button></div></div></div>`;document.querySelectorAll('[data-delete-student-close]').forEach(button=>button.onclick=()=>{state.modal=null;document.querySelector('#modal-root').innerHTML='';});document.querySelector('[data-delete-student-confirm]')?.addEventListener('click',deleteSelectedStudent);}
async function deleteSelectedStudent(){const id=state.modal?.studentId;if(!id||state.busy==='delete-student')return;state.busy='delete-student';state.modal.error=null;renderDeleteStudentModal();try{await deleteStudent(id);await refreshData();state.selectedStudentId=null;state.studentMenuId=null;state.modal=null;document.querySelector('#modal-root').innerHTML='';state.screen='students';render();}catch(error){state.busy='';state.modal={step:'delete-student',studentId:id,error:error.message||'Unable to delete student.'};renderDeleteStudentModal();}finally{state.busy='';}}
function openConfirmDialog({title,body,confirmLabel='Delete',allowConfirm=true,action}){state.modal={step:'confirm',title,body,confirmLabel,allowConfirm,action,busy:false,error:null};renderModal();}
function renderConfirmModal(){const m=state.modal;document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal confirm-modal" role="dialog" aria-modal="true" aria-labelledby="confirm-dialog-title"><div class="modal-header"><div><h2 id="confirm-dialog-title">${escapeHtml(m.title)}</h2></div><button class="close" data-confirm-cancel aria-label="Close">×</button></div>${m.error?`<div class="modal-error">${escapeHtml(m.error)}</div>`:''}<p class="modal-copy">${escapeHtml(m.body)}</p><div class="modal-footer"><button class="button-cancel" data-confirm-cancel ${m.busy?'disabled':''}>Cancel</button><button class="button-danger" data-confirm-accept ${m.busy||!m.allowConfirm?'disabled':''}>${m.busy?'Working…':escapeHtml(m.confirmLabel)}</button></div></div></div>`;document.querySelectorAll('[data-confirm-cancel]').forEach(button=>button.onclick=()=>{if(state.modal?.busy)return;state.modal=null;document.querySelector('#modal-root').innerHTML='';});document.querySelector('[data-confirm-accept]')?.addEventListener('click',runConfirmDialog);}
async function runConfirmDialog(){const m=state.modal;if(!m||m.busy||!m.allowConfirm)return;state.modal={...m,busy:true,error:null};renderConfirmModal();try{await m.action();if(state.modal?.step==='confirm'){state.modal=null;document.querySelector('#modal-root').innerHTML='';}}catch(error){state.modal={...m,busy:false,error:error.message||'Unable to complete this action.'};renderConfirmModal();}}
function openAddGuardian(studentId){state.selectedStudentId=studentId;state.modal={step:'guardian-form',studentId,guardianId:null,name:'',relation:'Mom',phone:'',error:null,saving:false};renderModal();}
function openEditGuardian(guardianId){const s=state.students.find(candidate=>candidate.guardians?.some(guardian=>guardian.id===guardianId));const guardian=s?.guardians?.find(candidate=>candidate.id===guardianId);if(!guardian)return;state.selectedStudentId=s.id;state.modal={step:'guardian-form',studentId:s.id,guardianId,name:guardian.name,relation:guardian.relation||'Guardian',phone:guardian.phone||'',error:null,saving:false};renderModal();}
function openDeleteGuardian(guardianId){const s=state.students.find(candidate=>candidate.guardians?.some(guardian=>guardian.id===guardianId));const guardian=s?.guardians?.find(candidate=>candidate.id===guardianId);if(!guardian)return;const onlyGuardian=s&&s.guardians.length<=1;openConfirmDialog({title:'Delete guardian?',body:onlyGuardian?`${guardian.name||'This guardian'} is the only guardian on file for ${s.name}. Add another guardian first so calls and contact records stay connected.`:`Remove ${guardian.name||'this guardian'} from ${s.name}’s record? Their contact history stays with the student. This can’t be undone.`,confirmLabel:'Delete guardian',allowConfirm:!onlyGuardian,action:async()=>{await requireFacadeAction('deleteGuardian')(guardianId);await refreshData();}});}
function renderGuardianFormModal(){const m=state.modal;const editing=Boolean(m.guardianId);document.querySelector('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal guardian-form-modal" role="dialog" aria-modal="true" aria-labelledby="guardian-form-title"><div class="modal-header"><div><p class="eyebrow">Caseload</p><h2 id="guardian-form-title">${editing?'Edit guardian':'Add guardian'}</h2><p>${editing?'Update this guardian’s contact details.':'Add another guardian for this student.'}</p></div><button class="close" data-guardian-cancel aria-label="Close">×</button></div>${m.error?`<div class="modal-error">${escapeHtml(m.error)}</div>`:''}<div class="form-grid guardian-form-grid"><label>Parent / guardian name<input id="guardian-form-name" value="${escapeHtml(m.name)}" autocomplete="name" placeholder="e.g. Taylor Lee"></label><label>Relationship<select id="guardian-form-relation"><option ${m.relation==='Mom'?'selected':''}>Mom</option><option ${m.relation==='Dad'?'selected':''}>Dad</option><option ${m.relation==='Guardian'?'selected':''}>Guardian</option><option ${m.relation==='Other'?'selected':''}>Other</option></select></label><label>Phone number<input id="guardian-form-phone" value="${escapeHtml(m.phone)}" autocomplete="tel" placeholder="(415) 555-0199"></label></div><div class="modal-footer"><button class="button-cancel" data-guardian-cancel ${m.saving?'disabled':''}>Cancel</button><button class="button-primary" data-save-guardian ${m.saving||!m.name.trim()||!m.phone.trim()?'disabled':''}>${m.saving?'Saving…':editing?'Save changes':'Add guardian'}</button></div></div></div>`;document.querySelectorAll('[data-guardian-cancel]').forEach(button=>button.onclick=()=>{if(state.modal?.saving)return;state.modal=null;document.querySelector('#modal-root').innerHTML='';});document.querySelector('#guardian-form-name')?.addEventListener('input',event=>{state.modal.name=event.target.value;updateGuardianFormSaveState();});document.querySelector('#guardian-form-relation')?.addEventListener('change',event=>{state.modal.relation=event.target.value;});document.querySelector('#guardian-form-phone')?.addEventListener('input',event=>{state.modal.phone=event.target.value;updateGuardianFormSaveState();});document.querySelector('[data-save-guardian]')?.addEventListener('click',saveGuardianForm);}
function updateGuardianFormSaveState(){const button=document.querySelector('[data-save-guardian]');if(button)button.disabled=state.modal.saving||!state.modal.name.trim()||!state.modal.phone.trim();}
async function saveGuardianForm(){const m=state.modal;if(!m||m.saving||!m.name.trim()||!m.phone.trim())return;state.modal={...m,saving:true,error:null};renderGuardianFormModal();try{const payload={name:m.name.trim(),relation:m.relation,phone:m.phone.trim()};if(m.guardianId)await requireFacadeAction('updateGuardian')(m.guardianId,payload);else await requireFacadeAction('createGuardian')({studentId:m.studentId,...payload});state.modal=null;document.querySelector('#modal-root').innerHTML='';await refreshData();}catch(error){state.modal={...m,saving:false,error:error.message||'Unable to save this guardian.'};renderGuardianFormModal();}}
document.addEventListener('click',event=>{const toggle=event.target.closest?.('[data-action="toggle-student-menu"]');if(toggle){event.preventDefault();event.stopPropagation();state.studentMenuId=state.studentMenuId===toggle.dataset.studentId?null:toggle.dataset.studentId;render();return;}const edit=event.target.closest?.('[data-action="edit-student"]');if(edit){event.preventDefault();event.stopPropagation();openEditStudent(edit.dataset.studentId);return;}const remove=event.target.closest?.('[data-action="delete-student"]');if(remove){event.preventDefault();event.stopPropagation();openDeleteStudent(remove.dataset.studentId);}});
if(AUTH_REQUIRED)initializeAuth();else refreshData().then(()=>{if(TELEPHONY_PROVIDER==='twilio')syncCallAndRefresh();});
